package com.chromatick;

import com.chromatick.Enums.*;
import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;

/**
 * Settings page only exposes hotkeys. All visual settings (cycle length,
 * per-cycle palettes, static colors, tile appearance) live in the sidebar
 * panel — the config values below are still used for persistence but are
 * hidden from the settings UI.
 */
@ConfigGroup("chromatick")
public interface ChromatickConfig extends Config
{
	// ─── Hidden state (driven by the sidebar panel) ─────────────────────

	@ConfigItem(keyName = "staticMode", name = "", description = "", hidden = true)
	default boolean staticMode()
	{
		return false;
	}

	@ConfigItem(keyName = "staticColor", name = "", description = "", hidden = true)
	default Color staticColor()
	{
		return new Color(0, 255, 0, 128);
	}

	@ConfigItem(keyName = "staticFillColor", name = "", description = "", hidden = true)
	default Color staticFillColor()
	{
		return new Color(0, 255, 0, 0);
	}

	@ConfigItem(keyName = "cycleLength", name = "", description = "", hidden = true)
	default int cycleLength()
	{
		return 4;
	}

	@ConfigItem(keyName = "tileBorderWidth", name = "", description = "", hidden = true)
	default double tileBorderWidth()
	{
		return 2;
	}

	@ConfigItem(keyName = "enableFillColor", name = "", description = "", hidden = true)
	default boolean enableFillColor()
	{
		return true;
	}

	@ConfigItem(keyName = "fillOpacity", name = "", description = "", hidden = true)
	default int fillOpacity()
	{
		return 50;
	}

	@ConfigItem(keyName = "drawBelowPlayer", name = "", description = "", hidden = true)
	default boolean drawBelowPlayer()
	{
		return false;
	}

	@ConfigItem(keyName = "paletteMode", name = "", description = "", hidden = true)
	default PaletteMode paletteMode()
	{
		return PaletteMode.GRID;
	}

	@ConfigItem(keyName = "sequentialFill", name = "", description = "", hidden = true)
	default boolean sequentialFill()
	{
		return true;
	}

	// ─── HUD overlay (chatbubble metronome) ─────────────────────────────

	/** Where the tick visualization renders. */
	@ConfigItem(keyName = "displayMode", name = "", description = "", hidden = true)
	default DisplayMode displayMode()
	{
		return DisplayMode.TILE;
	}

	/** Glyph style inside the HUD frame. */
	@ConfigItem(keyName = "hudGlyph", name = "", description = "", hidden = true)
	default HudGlyph hudGlyph()
	{
		return HudGlyph.DOTS;
	}

	/** 50–400, where 100 = native size. */
	@ConfigItem(keyName = "hudScale", name = "", description = "", hidden = true)
	default int hudScale()
	{
		return 200;
	}

	/** 0–100 opacity for the current tick. */
	@ConfigItem(keyName = "hudActiveOpacity", name = "", description = "", hidden = true)
	default int hudActiveOpacity()
	{
		return 100;
	}

	/** 0–100 opacity for the non-current ticks. */
	@ConfigItem(keyName = "hudInactiveOpacity", name = "", description = "", hidden = true)
	default int hudInactiveOpacity()
	{
		return 40;
	}

	/** Active glyph rendered in bold (Numbers variant only). */
	@ConfigItem(keyName = "hudBold", name = "", description = "", hidden = true)
	default boolean hudBold()
	{
		return false;
	}

	/** 0–200 extra-scale (%) on the active glyph; layout cells reserve space so siblings never shift. */
	@ConfigItem(keyName = "hudPop", name = "", description = "", hidden = true)
	default int hudPop()
	{
		return 0;
	}

	/** Pixel gap between glyphs at scale=100. Scales with hudScale. Negative = overlap. */
	@ConfigItem(keyName = "hudSpacing", name = "", description = "", hidden = true)
	default int hudSpacing()
	{
		return 0;
	}

	/** Stack glyphs top-to-bottom instead of left-to-right. */
	@ConfigItem(keyName = "hudVertical", name = "", description = "", hidden = true)
	default boolean hudVertical()
	{
		return false;
	}

	/** Where the HUD anchors to the player model. */
	@ConfigItem(keyName = "hudAnchorTarget", name = "", description = "", hidden = true)
	default HudAnchorTarget hudAnchorTarget()
	{
		return HudAnchorTarget.FEET;
	}

	/** Vertical offset (canvas px) from the anchor point to the HUD bar's center. */
	@ConfigItem(keyName = "hudVerticalOffset", name = "", description = "", hidden = true)
	default int hudVerticalOffset()
	{
		return 30;
	}

	/** Horizontal offset (canvas px) from the anchor point to the HUD bar's center. */
	@ConfigItem(keyName = "hudHorizontalOffset", name = "", description = "", hidden = true)
	default int hudHorizontalOffset()
	{
		return 0;
	}

	/** Render a single glyph that cycles color/number in place instead of a row of all ticks. */
	@ConfigItem(keyName = "hudCycleInPlace", name = "", description = "", hidden = true)
	default boolean hudCycleInPlace()
	{
		return false;
	}

	// ─── Per-tick action recorder ───────────────────────────────────────

	/** Recorder state: OFF, ARM (waits for movement) or ALWAYS (every tick). */
	@ConfigItem(keyName = "recordMode", name = "", description = "", hidden = true)
	default RecordMode recordMode()
	{
		return RecordMode.OFF;
	}

	/** Icon band placement relative to the HUD row. */
	@ConfigItem(keyName = "recordIconPosition", name = "", description = "", hidden = true)
	default IconPosition recordIconPosition()
	{
		return IconPosition.ABOVE;
	}

	/** In ARM mode, total ticks to capture (movement tick + N-1 more). 1..10. */
	@ConfigItem(keyName = "recordArmTicks", name = "", description = "", hidden = true)
	default int recordArmTicks()
	{
		return 1;
	}

	/**
	 * CSV of {@link TickActionCategory} names the recorder captures. The
	 * default is PROTECTION_PRAYER alone, matching the pre-categories
	 * behavior — existing users see no change until they enable more
	 * categories from the panel.
	 */
	@ConfigItem(keyName = "recordCategories", name = "", description = "", hidden = true)
	default String recordCategories()
	{
		return "PROTECTION_PRAYER";
	}

	// ─── Hotkeys ──────────────────────────────────────────────────────────

	@ConfigSection(
		name = "Hotkeys",
		description = "Hotkeys for controlling the tick overlay during gameplay",
		position = 1
	)
	String hotkeySettings = "hotkeySettings";

	@ConfigItem(
		position = 1,
		keyName = "toggleOverlayHotkey",
		name = "Toggle Static / Cycle",
		description = "Switch between static color mode and cycling mode. " +
			"The tile stays visible either way.",
		section = "hotkeySettings"
	)
	default Keybind toggleOverlayHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 2,
		keyName = "resetCycleHotkey",
		name = "Reset Cycle",
		description = "Reset the tick cycle to position 0 and clear any hotkey override",
		section = "hotkeySettings"
	)
	default Keybind resetCycleHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 3,
		keyName = "cycle2Hotkey",
		name = "2-Tick Cycle",
		description = "Switch to a 2-tick cycle",
		section = "hotkeySettings"
	)
	default Keybind cycle2Hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 4,
		keyName = "cycle3Hotkey",
		name = "3-Tick Cycle",
		description = "Switch to a 3-tick cycle",
		section = "hotkeySettings"
	)
	default Keybind cycle3Hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 5,
		keyName = "cycle4Hotkey",
		name = "4-Tick Cycle",
		description = "Switch to a 4-tick cycle",
		section = "hotkeySettings"
	)
	default Keybind cycle4Hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 6,
		keyName = "cycle5Hotkey",
		name = "5-Tick Cycle",
		description = "Switch to a 5-tick cycle",
		section = "hotkeySettings"
	)
	default Keybind cycle5Hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 7,
		keyName = "cycle6Hotkey",
		name = "6-Tick Cycle",
		description = "Switch to a 6-tick cycle",
		section = "hotkeySettings"
	)
	default Keybind cycle6Hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 8,
		keyName = "cycle7Hotkey",
		name = "7-Tick Cycle",
		description = "Switch to a 7-tick cycle",
		section = "hotkeySettings"
	)
	default Keybind cycle7Hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 9,
		keyName = "cycle8Hotkey",
		name = "8-Tick Cycle",
		description = "Switch to an 8-tick cycle",
		section = "hotkeySettings"
	)
	default Keybind cycle8Hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 10,
		keyName = "cycle9Hotkey",
		name = "9-Tick Cycle",
		description = "Switch to a 9-tick cycle",
		section = "hotkeySettings"
	)
	default Keybind cycle9Hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 11,
		keyName = "cycle10Hotkey",
		name = "10-Tick Cycle",
		description = "Switch to a 10-tick cycle",
		section = "hotkeySettings"
	)
	default Keybind cycle10Hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		position = 12,
		keyName = "recordModeHotkey",
		name = "Cycle Recorder Mode",
		description = "Cycle the per-tick recorder through OFF, ARM and ALWAYS",
		section = "hotkeySettings"
	)
	default Keybind recordModeHotkey()
	{
		return Keybind.NOT_SET;
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * One-shot migration of legacy config values that pre-date the move to enum-typed
 * config getters. Pre-1.0 the four enum keys (displayMode/hudGlyph/hudAnchorTarget/
 * paletteMode) were stored as raw lowercase strings; once the getters return enums
 * those raw values fail to deserialize and silently snap to the default. This
 * helper rewrites legacy values to their canonical {@code Enum#name()} form.
 *
 * <p>Idempotent — already-migrated values are no-ops, so running on every
 * {@code startUp} is safe.
 */
@Singleton
class ChromatickConfigMigrator
{
	private static final String GROUP = "chromatick";

	private final ConfigManager configManager;

	@Inject
	ChromatickConfigMigrator(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * Run all known migrations. Safe to call repeatedly.
	 *
	 * <p>Only the four pre-1.0 enum keys are migrated. {@code recordMode} and
	 * {@code recordIconPosition} are also enum-typed config getters but were
	 * introduced after the stringly-typed era, so no legacy lowercase form
	 * exists for them.
	 */
	void migrate()
	{
		migrateEnumKey("displayMode", DisplayMode.class);
		migrateEnumKey("hudGlyph", HudGlyph.class);
		migrateEnumKey("hudAnchorTarget", HudAnchorTarget.class);
		migrateEnumKey("paletteMode", PaletteMode.class);
	}

	private <T extends Enum<T>> void migrateEnumKey(String key, Class<T> enumType)
	{
		String raw = configManager.getConfiguration(GROUP, key);
		if (raw == null || raw.isEmpty())
		{
			return;
		}
		try
		{
			Enum.valueOf(enumType, raw);
			return; // already in canonical form
		}
		catch (IllegalArgumentException ignored)
		{
			// fall through to migration attempt
		}
		try
		{
			T migrated = Enum.valueOf(enumType, raw.toUpperCase(Locale.ROOT));
			configManager.setConfiguration(GROUP, key, migrated.name());
		}
		catch (IllegalArgumentException ignored)
		{
			// Unknown legacy value — leave it so RuneLite falls back to default.
		}
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.awt.Canvas;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * HUD metronome — a frameless row (or column) of palette-colored glyphs.
 *
 * Anchoring: target is HEAD, FEET, or NONE. HEAD and FEET auto-position the
 * bar each frame relative to the player (with X/Y offsets layered on top).
 * Alt+drag flips the target to NONE — the bar stays where the user dropped
 * it. The panel pill toggle lets the user re-anchor explicitly.
 *
 * Static mode only freezes the *color* (all glyphs use the static color); the
 * tick cycle still advances and the active glyph still moves through the slots.
 */
public class ChromatickHudOverlay extends Overlay
{
	private final ChromatickPlugin plugin;
	private final ChromatickConfig config;
	private final Client client;
	private final PaletteService palettes;
	private final TickRecorderService recorder;
	private final RecordedIconResolver iconResolver;

	/**
	 * The location we last set on the overlay ourselves; used to detect user drag.
	 * Volatile because clearDragState() may run on the Swing EDT (panel callbacks)
	 * while render runs on the client thread — same rationale as userDragged below.
	 */
	private volatile Point lastSetLocation = null;
	/** Last canvas dimensions; if they change between frames, skip drag-detection that frame. */
	private int lastCanvasW = -1;
	private int lastCanvasH = -1;

	/**
	 * Signal that render() detected an alt-drag. The plugin drains this flag
	 * on its next game tick and flips the anchor target to NONE. Volatile
	 * because clearDragState() may run on the Swing EDT (panel callbacks)
	 * while render runs on the client thread.
	 */
	private volatile boolean userDragged = false;

	@Inject
	ChromatickHudOverlay(ChromatickPlugin plugin, ChromatickConfig config, Client client,
		PaletteService palettes, TickRecorderService recorder, RecordedIconResolver iconResolver)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.client = client;
		this.palettes = palettes;
		this.recorder = recorder;
		this.iconResolver = iconResolver;
		setPosition(OverlayPosition.DYNAMIC);
		setMovable(true);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final int cycleLength = plugin.getEffectiveCycleLength();
		if (cycleLength < 1)
		{
			return null;
		}

		// Track canvas dimensions — when the user resizes the RuneLite window,
		// the framework can nudge our overlay's position to keep it in bounds.
		// That nudge would otherwise look like a user drag, so skip drag
		// detection on the frame after a resize.
		final Canvas canvas = client.getCanvas();
		final int canvasW = canvas != null ? canvas.getWidth()  : 0;
		final int canvasH = canvas != null ? canvas.getHeight() : 0;
		final boolean canvasResized = (canvasW != lastCanvasW || canvasH != lastCanvasH);
		lastCanvasW = canvasW;
		lastCanvasH = canvasH;

		// Drag detection: if we *think* we're anchored but the framework's
		// preferred location no longer matches what we last set, the user must
		// have alt-dragged the overlay. Set userDragged so subsequent frames
		// stop re-anchoring; the plugin observes the flag on its next game
		// tick and flips the persisted anchor target to NONE.
		HudAnchorTarget anchorTarget = config.hudAnchorTarget();
		boolean anchored = anchorTarget != HudAnchorTarget.NONE && !userDragged;
		if (anchored && wasDragged(canvasResized, lastSetLocation, getPreferredLocation()))
		{
			userDragged = true;
			lastSetLocation = null;
			anchored = false;
		}

		final int currentTick = Math.floorMod(plugin.getTickIndex(), cycleLength);
		final Color[] palette = resolvePalette(cycleLength);
		final boolean cycleInPlace = config.hudCycleInPlace();
		final RecordMode recordMode = recorder.getMode();
		// Keep icons visible after a one-shot ARM has auto-exited so the user
		// can review the recording. Hidden only when mode is OFF AND there's
		// nothing to show.
		final boolean wantIcons = recordMode != RecordMode.OFF || recorder.hasCaptures();
		// Combo layout reserves a second icon band alongside the primary so
		// ITEM_USE renders source + target in stacked lanes (same side of the
		// glyph row) instead of cramming both into one slot.
		final boolean comboCapable = plugin.enabledRecordCategories()
			.contains(TickActionCategory.ITEM_USE);

		final HudLayout layout = HudLayout.compute(
			config.hudScale(),
			config.hudPop(),
			config.hudSpacing(),
			cycleLength,
			config.hudVertical(),
			cycleInPlace,
			wantIcons,
			config.recordIconPosition(),
			comboCapable
		);

		if (layout.showIcons)
		{
			iconResolver.ensureLoaded();
		}

		// While anchored, place the overlay so the bar's center sits at the
		// configured offset from the player's head/feet. We always overwrite
		// the framework's preferred location so the HUD follows the player
		// every frame (and re-positions correctly after window resizes).
		if (anchored)
		{
			Point base = anchorTarget == HudAnchorTarget.HEAD
				? computePlayerHeadCanvasPoint()
				: computePlayerFeetCanvasPoint();
			if (base != null)
			{
				int xOff = config.hudHorizontalOffset();
				int yOff = config.hudVerticalOffset();
				int x = base.x + xOff - layout.totalWidth / 2;
				int y = base.y + yOff - layout.totalHeight / 2;
				Point newLoc = new Point(x, y);
				setPreferredLocation(newLoc);
				lastSetLocation = newLoc;
			}
		}

		final int activeAlpha   = pctToAlpha(config.hudActiveOpacity());
		final int inactiveAlpha = pctToAlpha(config.hudInactiveOpacity());
		final boolean useBold   = config.hudBold();
		final HudGlyph glyphType = config.hudGlyph();

		for (int k = 0; k < layout.slots; k++)
		{
			// In cycle-in-place mode the single slot always shows the current
			// tick's palette entry and counts as "active". In row mode, slot k
			// maps to palette[k] and is active only when k == currentTick.
			final int paletteSlot = cycleInPlace ? currentTick : k;
			final boolean active  = cycleInPlace || (k == currentTick);
			final int alpha       = active ? activeAlpha : inactiveAlpha;
			final Color base      = palette[paletteSlot % palette.length];
			final Color glyphCol  = new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha);

			final int cx = layout.cellCenterX(k);
			final int cy = layout.cellCenterY(k);
			final int glyphSize = layout.glyphSize(active);

			if (glyphType == HudGlyph.NUMBERS)
			{
				renderNumber(g, paletteSlot + 1, cx, cy, glyphSize, glyphCol, active && useBold);
			}
			else
			{
				renderDot(g, cx, cy, glyphSize, glyphCol);
			}

			// Recorded prayer icon for this tick (row mode only).
			if (layout.showIcons)
			{
				renderRecordedIcon(g, layout, k);
			}
		}

		// Minimal mode indicator — tiny colored dot in a glyph-row corner so it
		// always sits opposite the icon band(s). Sits inside the bounding box
		// so the framework's drag-tracking sees it as part of the overlay.
		if (recordMode != RecordMode.OFF)
		{
			renderModeIndicator(g, layout, recordMode);
		}

		return new Dimension(layout.totalWidth, layout.totalHeight);
	}

	/**
	 * Clear the drag-tracking state so the next render() re-anchors cleanly.
	 * Called from the plugin's setHudAnchorTarget after switching off NONE,
	 * and on plugin startUp when re-adding the overlay.
	 */
	void clearDragState()
	{
		lastSetLocation = null;
		userDragged = false;
	}

	/**
	 * Read-and-clear: returns {@code true} once for each render-detected drag,
	 * then resets the flag. The plugin calls this on each game tick so the
	 * persisted anchor target can flip to NONE without render mutating state.
	 */
	boolean consumeUserDragged()
	{
		if (userDragged)
		{
			userDragged = false;
			return true;
		}
		return false;
	}

	/**
	 * True when the framework's preferred location no longer matches what we
	 * last set, meaning the user alt-dragged the overlay. Pure predicate —
	 * extracted from render() so the edge cases (window resize, null seed
	 * location, missing preferred location) can be pinned down with unit
	 * tests without standing up a render context.
	 */
	static boolean wasDragged(boolean canvasResized, Point lastSet, Point current)
	{
		if (canvasResized || lastSet == null || current == null)
		{
			return false;
		}
		return !current.equals(lastSet);
	}

	/** Player's feet at ground level in canvas pixel space, or null if unavailable. */
	private Point computePlayerFeetCanvasPoint()
	{
		Player p = client.getLocalPlayer();
		if (p == null)
		{
			return null;
		}
		LocalPoint lp = p.getLocalLocation();
		if (lp == null)
		{
			return null;
		}
		net.runelite.api.Point pt = Perspective.localToCanvas(
			client, lp, client.getTopLevelWorldView().getPlane());
		if (pt == null)
		{
			return null;
		}
		return new Point(pt.getX(), pt.getY());
	}

	/** Player's head (top of model) in canvas pixel space, or null if unavailable. */
	private Point computePlayerHeadCanvasPoint()
	{
		Player p = client.getLocalPlayer();
		if (p == null)
		{
			return null;
		}
		LocalPoint lp = p.getLocalLocation();
		if (lp == null)
		{
			return null;
		}
		net.runelite.api.Point pt = Perspective.localToCanvas(
			client, lp, client.getTopLevelWorldView().getPlane(), p.getLogicalHeight());
		if (pt == null)
		{
			return null;
		}
		return new Point(pt.getX(), pt.getY());
	}

	private Color[] resolvePalette(int cycleLength)
	{
		if (config.staticMode())
		{
			Color sc = config.staticColor();
			Color opaque = new Color(sc.getRed(), sc.getGreen(), sc.getBlue());
			Color[] arr = new Color[cycleLength];
			for (int i = 0; i < cycleLength; i++)
			{
				arr[i] = opaque;
			}
			return arr;
		}
		return palettes.getCustomPaletteForCycle(cycleLength);
	}

	private void renderDot(Graphics2D g, int cx, int cy, int size, Color color)
	{
		// Fully transparent glyph → no shadow either. Without this guard the
		// shadow alpha would clamp up to 80 and leave a ghost at opacity 0.
		if (color.getAlpha() == 0)
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int shadowAlpha = Math.max(color.getAlpha(), 80);
		g2.setColor(new Color(0, 0, 0, shadowAlpha));
		g2.fillOval(cx - size / 2 + 1, cy - size / 2 + 1, size, size);

		g2.setColor(color);
		g2.fillOval(cx - size / 2, cy - size / 2, size, size);
		g2.dispose();
	}

	private void renderNumber(Graphics2D g, int number, int cx, int cy, int size, Color color, boolean bold)
	{
		if (color.getAlpha() == 0)
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		Font font = FontManager.getRunescapeSmallFont();
		if (bold)
		{
			font = font.deriveFont(Font.BOLD);
		}
		font = font.deriveFont(Math.max(9f, size * 1.0f));
		g2.setFont(font);

		String s = String.valueOf(number);
		FontMetrics fm = g2.getFontMetrics();
		int textW = fm.stringWidth(s);
		int textH = fm.getAscent();
		int baseX = cx - textW / 2;
		int baseY = cy + textH / 2 - 1;

		int shadowAlpha = Math.max(color.getAlpha(), 80);
		g2.setColor(new Color(0, 0, 0, shadowAlpha));
		g2.drawString(s, baseX + 1, baseY + 1);
		g2.setColor(color);
		g2.drawString(s, baseX, baseY);
		g2.dispose();
	}

	private static int pctToAlpha(int pct)
	{
		return Math.round(clamp(pct, 0, 100) * 2.55f);
	}

	private static int clamp(int v, int lo, int hi)
	{
		return Math.max(lo, Math.min(hi, v));
	}

	// ─── Per-tick recorder ──────────────────────────────────────────────

	/**
	 * Render the recorded icon (if any) for tick slot {@code k}. Sprite,
	 * combo (two sprites), or primitive-dot is decided in
	 * {@link RecordedIconResolver}; the overlay just draws what it gets.
	 */
	private void renderRecordedIcon(Graphics2D g, HudLayout layout, int k)
	{
		RecordedIcon icon = iconResolver.iconFor(recorder.getRecordedAt(k));
		if (icon == null)
		{
			return;
		}
		int size = layout.glyphSize(false);
		int cx = layout.iconCenterX(k);
		int cy = layout.iconCenterY(k);
		if (icon.sprite != null)
		{
			g.drawImage(icon.sprite, cx - size / 2, cy - size / 2, size, size, null);
		}
		else
		{
			// Primitive dot — antialiased filled oval at the icon slot.
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(icon.primitiveColor);
			g2.fillOval(cx - size / 2, cy - size / 2, size, size);
			g2.dispose();
		}
		if (icon.isCombo() && layout.comboLayout)
		{
			int sx = layout.comboIconCenterX(k);
			int sy = layout.comboIconCenterY(k);
			g.drawImage(icon.secondarySprite, sx - size / 2, sy - size / 2, size, size, null);
		}
	}

	private void renderModeIndicator(Graphics2D g, HudLayout layout, RecordMode mode)
	{
		Color dotColor;
		switch (mode)
		{
			case ARM:    dotColor = new Color(255, 180, 30); break;  // amber
			case ALWAYS: dotColor = new Color(220, 50,  50); break;  // red
			default: return;
		}
		// Anchor in the corner opposite the icon band(s). For horizontal
		// layouts the band sits ABOVE or BELOW the glyph row, so the dot
		// flips between top-left and bottom-left. For vertical layouts the
		// band sits LEFT (ABOVE) or RIGHT (BELOW) of the glyph column, so
		// the dot flips between top-left and top-right. In all cases the
		// dot is on the glyph row's far side from the icons.
		final boolean iconsAbove = layout.iconPosition == IconPosition.ABOVE;
		final int x = (layout.vertical && iconsAbove) ? layout.totalWidth - 2 - 5 : 2;
		final int y = (!layout.vertical && iconsAbove) ? layout.totalHeight - 2 - 5 : 2;
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(new Color(0, 0, 0, 160));
		g2.fillOval(x, y, 5, 5);
		g2.setColor(dotColor);
		g2.fillOval(x, y, 4, 4);
		g2.dispose();
	}
}

package com.chromatick;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class ChromatickOverlay extends Overlay
{
	private final Client client;
	private final ChromatickConfig config;
	private final ChromatickPlugin plugin;

	@Inject
	public ChromatickOverlay(Client client, ChromatickConfig config, ChromatickPlugin plugin)
	{
		super(plugin);
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final WorldPoint playerPos = client.getLocalPlayer().getWorldLocation();
		if (playerPos == null)
		{
			return null;
		}

		final LocalPoint playerPosLocal = LocalPoint.fromWorld(client, playerPos);
		if (playerPosLocal == null)
		{
			return null;
		}

		final Color borderColor = plugin.getCurrentColor();
		final Color fillColor;

		if (config.enableFillColor())
		{
			// fillOpacity is the single source of truth for fill alpha in both modes.
			// In static mode the static-fill swatch only contributes RGB.
			final Color fillRgb = config.staticMode() ? config.staticFillColor() : borderColor;
			fillColor = new Color(
				fillRgb.getRed(),
				fillRgb.getGreen(),
				fillRgb.getBlue(),
				config.fillOpacity()
			);
		}
		else
		{
			fillColor = new Color(0, 0, 0, 0);
		}

		renderTile(graphics, playerPosLocal, borderColor, fillColor, config.tileBorderWidth());

		if (config.drawBelowPlayer() && client.isGpu())
		{
			removePlayer(graphics, client.getLocalPlayer());
		}

		return null;
	}

	private void renderTile(Graphics2D graphics, LocalPoint dest, Color color, Color fillColor, double borderWidth)
	{
		final Polygon poly = Perspective.getCanvasTilePoly(client, dest);
		if (poly == null)
		{
			return;
		}
		OverlayUtil.renderPolygon(graphics, poly, color, fillColor, new BasicStroke((float) borderWidth));
	}

	// ─── Draw below player ───────────────────────────────────────────────────
	// Adapted from LeikvollE's Improved Tile Indicators (BSD-2 Clause)
	// https://github.com/LeikvollE/tileindicators
	//
	// After the tile polygon is drawn onto ABOVE_SCENE, the player model's
	// front-facing triangles are projected to 2D canvas space and filled with
	// AlphaComposite.Clear, punching holes through the overlay so the player
	// model visually appears on top of the tile. GPU rendering mode required.

	private void removePlayer(final Graphics2D graphics, final Player player)
	{
		final int localZ = Perspective.getFootprintTileHeight(
			client,
			player.getLocalLocation(),
			client.getTopLevelWorldView().getPlane(),
			player.getFootprintSize()
		) - player.getAnimationHeightOffset();
		removeActor(graphics, player, localZ);
	}

	private void removeActor(final Graphics2D graphics, final Actor actor, final int localZ)
	{
		// Either of these can be null transiently — model during animation/region
		// transitions, local location when the actor is off-scene. Bail before
		// dereferencing, otherwise the overlay NPEs in render.
		final Model model = actor.getModel();
		final LocalPoint lp = actor.getLocalLocation();
		if (model == null || lp == null)
		{
			return;
		}

		final int clipX1 = client.getViewportXOffset();
		final int clipY1 = client.getViewportYOffset();
		final int clipX2 = client.getViewportWidth() + clipX1;
		final int clipY2 = client.getViewportHeight() + clipY1;

		final Object origAA = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

		final int vCount = model.getVerticesCount();
		final float[] x3d = model.getVerticesX();
		final float[] y3d = model.getVerticesY();
		final float[] z3d = model.getVerticesZ();

		final int[] x2d = new int[vCount];
		final int[] y2d = new int[vCount];

		Perspective.modelToCanvas(
			client, client.getTopLevelWorldView(), vCount,
			lp.getX(), lp.getY(), localZ,
			actor.getCurrentOrientation(),
			x3d, z3d, y3d,
			x2d, y2d
		);

		boolean anyVisible = false;
		for (int i = 0; i < vCount; i++)
		{
			anyVisible |= x2d[i] >= clipX1 && x2d[i] < clipX2
				&& y2d[i] >= clipY1 && y2d[i] < clipY2;
		}
		if (!anyVisible)
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, origAA);
			return;
		}

		final int tCount = model.getFaceCount();
		final int[] tx = model.getFaceIndices1();
		final int[] ty = model.getFaceIndices2();
		final int[] tz = model.getFaceIndices3();
		final byte[] transparencies = model.getFaceTransparencies();

		final Composite orig = graphics.getComposite();
		graphics.setComposite(AlphaComposite.Clear);
		graphics.setColor(Color.WHITE);

		for (int i = 0; i < tCount; i++)
		{
			if (getTriDirection(
				x2d[tx[i]], y2d[tx[i]],
				x2d[ty[i]], y2d[ty[i]],
				x2d[tz[i]], y2d[tz[i]]) >= 0)
			{
				continue;
			}
			if (transparencies != null && (transparencies[i] & 0xFF) >= 254)
			{
				continue;
			}
			graphics.fill(new Polygon(
				new int[]{x2d[tx[i]], x2d[ty[i]], x2d[tz[i]]},
				new int[]{y2d[tx[i]], y2d[ty[i]], y2d[tz[i]]},
				3
			));
		}

		graphics.setComposite(orig);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, origAA);
	}

	// 2D cross product — positive means back-facing (cull), negative means front-facing (draw)
	private int getTriDirection(int x1, int y1, int x2, int y2, int x3, int y3)
	{
		return (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
	}
}

