		fillTileGlyph.setFilled(s.enableFillColor);
		setOpacityControls(s.fillOpacity);
		fillOpacitySlider.setEnabled(s.enableFillColor);
		fillOpacityValueLabel.setEnabled(s.enableFillColor);
