	private void onPickerColor(Color c)
	{
		updateHex(c);
		if (editing != null)
		{
			editing.applyColor(c);
		}
	}

	private void onPickerCommit()
	{
		if (sequentialFill.isSelected()
			&& editing instanceof TickSwatch
			&& !plugin.isStaticMode())
		{
			int next = (((TickSwatch) editing).index + 1) % selectedCycle;
			selectTickSlot(next);
		}
	}

