	// ─── Slot abstraction ─────────────────────────────────────────────────

	private interface Slot
	{
		Color getColor();
		void applyColor(Color c);
	}

	// ─── Tick swatch ──────────────────────────────────────────────────────

	private class TickSwatch extends JPanel implements Slot
	{
		final int index;
		private Color   color;
		private boolean selected;

		TickSwatch(int index, Color color)
		{
			this.index = index;
			this.color = color;
			setPreferredSize(new Dimension(28, 30));
			setOpaque(false);
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			setToolTipText("Tick " + (index + 1));
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					selectTickSlot(index);
				}
			});
		}

		@Override
		public Color getColor()
		{
			return color;
		}

		@Override
		public void applyColor(Color c)
		{
			color = c;
			palettes.setCustomPaletteColor(selectedCycle, index, c);
			repaint();
		}

		void setColor(Color c)
		{
			color = c;
			repaint();
		}

		void setSelected(boolean sel)
		{
			selected = sel;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();

			if (selected)
			{
				g2.setColor(ColorScheme.BRAND_ORANGE);
				g2.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.drawRoundRect(1, 1, w - 2, h - 2, 6, 6);
				g2.setColor(color);
				g2.fillRoundRect(3, 3, w - 6, h - 6, 4, 4);
			}
			else
			{
				g2.setColor(color);
				g2.fillRoundRect(0, 0, w, h, 6, 6);
				g2.setColor(new Color(0, 0, 0, 70));
				g2.setStroke(new BasicStroke(1f));
				g2.drawRoundRect(0, 0, w - 1, h - 1, 6, 6);
			}

			// Tick number — bold, contrast-aware
			Font bold = FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD);
			g2.setFont(bold);
			String s    = String.valueOf(index + 1);
			double luma = 0.299 * color.getRed() + 0.587 * color.getGreen() + 0.114 * color.getBlue();
			g2.setColor(luma > 140 ? Color.BLACK : Color.WHITE);
			int sw = g2.getFontMetrics().stringWidth(s);
			int sh = g2.getFontMetrics().getAscent();
			g2.drawString(s, (w - sw) / 2, (h + sh) / 2 - 2);
			g2.dispose();
		}
	}

	// ─── Static swatch ────────────────────────────────────────────────────

	private class StaticSwatch extends JPanel implements Slot
	{
		private final String  label;
		private final boolean border;
		private Color         color;
		private boolean       selected;

		StaticSwatch(String label, boolean border, Color initial)
		{
			this.label  = label;
			this.border = border;
			this.color  = initial;
			setPreferredSize(new Dimension(72, 48));
			setOpaque(false);
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			setToolTipText("Click to edit " + label.toLowerCase());
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					selectStaticSwatch(StaticSwatch.this);
				}
			});
		}

		@Override
		public Color getColor()
		{
			return color;
		}

		@Override
		public void applyColor(Color c)
		{
			Color withAlpha = new Color(c.getRed(), c.getGreen(), c.getBlue(), color.getAlpha());
			color = withAlpha;
			if (border)
			{
				plugin.setStaticColor(withAlpha);
			}
			else
			{
				plugin.setStaticFillColor(withAlpha);
			}
			repaint();
		}

		void setColor(Color c)
		{
			color = c;
			repaint();
		}

		void setSelected(boolean sel)
		{
			selected = sel;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();
			Color opaque = new Color(color.getRed(), color.getGreen(), color.getBlue());

			if (selected)
			{
				g2.setColor(ColorScheme.BRAND_ORANGE);
				g2.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.drawRoundRect(1, 1, w - 2, h - 2, 6, 6);
				g2.setColor(opaque);
				g2.fillRoundRect(3, 3, w - 6, h - 6, 4, 4);
			}
			else
			{
				g2.setColor(opaque);
				g2.fillRoundRect(0, 0, w, h, 6, 6);
				g2.setColor(new Color(0, 0, 0, 70));
				g2.setStroke(new BasicStroke(1f));
				g2.drawRoundRect(0, 0, w - 1, h - 1, 6, 6);
			}

			g2.setFont(FontManager.getRunescapeSmallFont());
			double luma = 0.299 * color.getRed() + 0.587 * color.getGreen() + 0.114 * color.getBlue();
			g2.setColor(luma > 140 ? Color.BLACK : Color.WHITE);
			int sw = g2.getFontMetrics().stringWidth(label);
			g2.drawString(label, (w - sw) / 2, h - 6);
			g2.dispose();
		}
	}

	// ─── Cycle tab button ─────────────────────────────────────────────────

	private class CycleTabButton extends JPanel
	{
		final int     cycle;
		private final JLabel label;
		private boolean tabSelected;
		private boolean tabEnabled = true;

		CycleTabButton(int cycle)
		{
			this.cycle = cycle;
			setLayout(new BorderLayout());
			setOpaque(false);
			setBorder(new EmptyBorder(4, 0, 4, 0));
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			label = new JLabel(String.valueOf(cycle), SwingConstants.CENTER);
			label.setFont(FontManager.getRunescapeSmallFont());
			label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			add(label, BorderLayout.CENTER);
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (!tabEnabled)
					{
						return;
					}
					if (cycle != selectedCycle)
					{
						plugin.setActiveCycle(cycle);
					}
				}
			});
		}

		void setTabSelected(boolean sel)
		{
			tabSelected = sel;
			applyLabelColor();
			repaint();
		}

		void setTabEnabled(boolean en)
		{
			tabEnabled = en;
			setCursor(en ? Cursor.getPredefinedCursor(Cursor.HAND_CURSOR) : Cursor.getDefaultCursor());
			applyLabelColor();
			repaint();
		}

		private void applyLabelColor()
		{
			if (!tabEnabled)
			{
				label.setForeground(TEXT_DIM);
			}
			else if (tabSelected)
			{
				label.setForeground(Color.BLACK);
			}
			else
			{
				label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			}
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			Color fill;
			if (!tabEnabled)
			{
				fill = tabSelected ? new Color(0x5C3F1A) : new Color(0x252525);
			}
			else
			{
				fill = tabSelected ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR;
			}
			g2.setColor(fill);
			g2.fillRoundRect(0, 0, getWidth(), getHeight(), 5, 5);
			g2.dispose();
		}
	}

	// ─── Pill toggle ──────────────────────────────────────────────────────

	private class PillToggle extends JPanel
	{
		// Fixed pill height so every PillToggle instance is the same height
		// regardless of label font. Without this, the runescape pixel font and
		// sans-serif (used for unicode glyphs) produce different preferred
		// heights and the toggles end up visually inconsistent.
		private static final int PILL_HEIGHT = 22;

		private final List<JLabel> pills = new ArrayList<>();
		private int selected = 0;
		private IntConsumer listener;

		PillToggle(String[] options)
		{
			setLayout(new GridLayout(1, options.length, 2, 0));
			setOpaque(false);
			setBorder(new EmptyBorder(2, 2, 2, 2));
			setMinimumSize(new Dimension(0, PILL_HEIGHT));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, PILL_HEIGHT));

			for (int i = 0; i < options.length; i++)
			{
				final int idx = i;
				JLabel pill = new JLabel(options[i], SwingConstants.CENTER)
				{
					final int pillIdx = idx;

					@Override
					protected void paintComponent(Graphics g)
					{
						if (pillIdx == selected)
						{
							Graphics2D g2 = (Graphics2D) g.create();
							g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
							g2.setColor(ColorScheme.BRAND_ORANGE);
							g2.fillRoundRect(0, 0, getWidth(), getHeight(), 4, 4);
							g2.dispose();
						}
						super.paintComponent(g);
					}
				};
				pill.setOpaque(false);
				pill.setFont(FontManager.getRunescapeSmallFont());
				pill.setBorder(new EmptyBorder(3, 6, 3, 6));
				pill.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				pill.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mousePressed(MouseEvent e)
					{
						if (idx != selected)
						{
							setSelected(idx);
							if (listener != null)
							{
								listener.accept(idx);
							}
						}
					}
				});
				pills.add(pill);
				add(pill);
			}
			applyStyles();
		}

		void setSelected(int idx)
		{
			selected = idx;
			applyStyles();
		}

		void addListener(IntConsumer l)
		{
			listener = l;
		}

		/** Override the pill label font — used when labels need unicode glyphs the runescape pixel font lacks. */
		void setPillFont(Font f)
		{
			for (JLabel pill : pills)
			{
				pill.setFont(f);
			}
		}

		/** Per-pill tooltips — handy when the visual label alone is ambiguous (e.g. ● vs 1). */
		void setPillTooltips(String[] tips)
		{
			for (int i = 0; i < pills.size() && i < tips.length; i++)
			{
				pills.get(i).setToolTipText(tips[i]);
			}
		}

		/** Update the visible pill labels in place — used when the same pill carries
		 *  context-dependent text (e.g. Above/Below vs. Left/Right). */
		void setPillLabels(String[] labels)
		{
			for (int i = 0; i < pills.size() && i < labels.length; i++)
			{
				pills.get(i).setText(labels[i]);
			}
			revalidate();
			repaint();
		}

		@Override
		public Dimension getPreferredSize()
		{
			// Width comes from the underlying layout; height is locked so all
			// pill toggles render at the same height regardless of label font.
			Dimension d = super.getPreferredSize();
			return new Dimension(d.width, PILL_HEIGHT);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(TRACK_BG);
			g2.fillRoundRect(0, 0, getWidth(), getHeight(), 6, 6);
			g2.dispose();
		}

		private void applyStyles()
		{
			for (int j = 0; j < pills.size(); j++)
			{
				pills.get(j).setForeground(j == selected ? Color.BLACK : ColorScheme.LIGHT_GRAY_COLOR);
				pills.get(j).repaint();
			}
			repaint();
		}
	}

	// ─── Multi-select icon pill row (capture categories) ────────────────

	/**
	 * Multi-select pill row whose pills render icons instead of text. Used
	 * for the recorder's capture-category selector — each pill maps to a
	 * {@link TickActionCategory} and toggles independently.
	 *
	 * <p>Icons come from {@link RecordedIconResolver#categoryIcon} which
	 * loads game sprites lazily. Until a sprite finishes loading the pill
	 * shows a small placeholder dot; subsequent paint cycles pick up the
	 * loaded image automatically — no callback wiring needed.
	 *
	 * <p>Same visual track + rounded-rect selection treatment as
	 * {@link PillToggle}, so the two widgets look like siblings in the
	 * Recorder block.
	 */
	private class IconPillRow extends JPanel
	{
		private static final int PILL_HEIGHT = 22;
		private static final int ICON_SIZE   = 16;

		private final TickActionCategory[] categories;
		private final IconPill[] pills;
		private BiConsumer<TickActionCategory, Boolean> listener;

		IconPillRow(TickActionCategory[] categories, String[] tooltips)
		{
			this.categories = categories;
			this.pills = new IconPill[categories.length];
			setLayout(new GridLayout(1, categories.length, 2, 0));
			setOpaque(false);
			setBorder(new EmptyBorder(2, 2, 2, 2));
			setMinimumSize(new Dimension(0, PILL_HEIGHT));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, PILL_HEIGHT));
			for (int i = 0; i < categories.length; i++)
			{
				pills[i] = new IconPill(categories[i]);
				if (tooltips != null && i < tooltips.length)
				{
					pills[i].setToolTipText(tooltips[i]);
				}
				add(pills[i]);
			}
		}

		void setSelected(TickActionCategory cat, boolean selected)
		{
			for (int i = 0; i < categories.length; i++)
			{
				if (categories[i] == cat)
				{
					pills[i].selected = selected;
					pills[i].repaint();
					return;
				}
			}
		}

		void setListener(BiConsumer<TickActionCategory, Boolean> l)
		{
			this.listener = l;
		}

		@Override
		public Dimension getPreferredSize()
		{
			Dimension d = super.getPreferredSize();
			return new Dimension(d.width, PILL_HEIGHT);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(TRACK_BG);
			g2.fillRoundRect(0, 0, getWidth(), getHeight(), 6, 6);
			g2.dispose();
		}

		/** One pill in the row — its icon comes from the category and its selected state is independent. */
		private class IconPill extends JComponent
		{
			final TickActionCategory category;
			boolean selected = false;

			IconPill(TickActionCategory category)
			{
				this.category = category;
				setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				addMouseListener(new MouseAdapter()
				{
					@Override
					public void mousePressed(MouseEvent e)
					{
						selected = !selected;
						repaint();
						if (listener != null)
						{
							listener.accept(category, selected);
						}
					}
				});
			}

			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

				if (selected)
				{
					g2.setColor(ColorScheme.BRAND_ORANGE);
					g2.fillRoundRect(0, 0, getWidth(), getHeight(), 4, 4);
				}

				BufferedImage icon = iconResolver.categoryIcon(category);
				int cx = getWidth() / 2;
				int cy = getHeight() / 2;
				if (icon != null)
				{
					// Faded when unselected so the active pills stand out without
					// the orange chip alone carrying the entire signal.
					if (!selected)
					{
						g2.setComposite(AlphaComposite.getInstance(
							AlphaComposite.SRC_OVER, 0.55f));
					}
					g2.drawImage(icon, cx - ICON_SIZE / 2, cy - ICON_SIZE / 2,
						ICON_SIZE, ICON_SIZE, null);
				}
				else
				{
					// Sprite not loaded yet — a small placeholder dot until the
					// next repaint catches the async load.
					g2.setColor(selected ? Color.BLACK : ColorScheme.LIGHT_GRAY_COLOR);
					g2.fillOval(cx - 4, cy - 4, 8, 8);
				}

				g2.dispose();
			}
		}
	}

	// ─── ChromaTick glyph (5 coloured bars) ──────────────────────────────

