	// ─── Player tile glyph (tile over/under player indicator) ────────────

	private static class PlayerTileGlyph extends JPanel
	{
		private static final int[] TILE_X = {2, 11, 20, 11};
		private static final int[] TILE_Y = {12, 7, 12, 17};

		private boolean below;

		PlayerTileGlyph(boolean below)
		{
			this.below = below;
			setPreferredSize(new Dimension(22, 18));
			setOpaque(false);
		}

		void setBelow(boolean b)
		{
			below = b;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			if (below)
			{
				paintTile(g2, 0.55f);
				paintPlayer(g2);
			}
			else
			{
				paintPlayer(g2);
				paintTile(g2, 0.65f);
			}
			g2.dispose();
		}

		private void paintTile(Graphics2D g2, float alpha)
		{
			Polygon tile = new Polygon(TILE_X, TILE_Y, 4);
			g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			g2.setColor(ColorScheme.BRAND_ORANGE);
			g2.fillPolygon(tile);
			g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1f));
			g2.setStroke(new BasicStroke(1f));
			g2.drawPolygon(tile);
		}

		private void paintPlayer(Graphics2D g2)
		{
			g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1f));
			g2.setColor(TEXT_BRIGHT);
			g2.fillOval(9, 4, 4, 4);
			g2.fillRoundRect(9, 8, 4, 6, 1, 1);
		}
	}

	// ─── Fill tile glyph (outline-only ↔ filled) ──────────────────────────

	private static class FillTileGlyph extends JPanel
	{
		private static final int[] TILE_X = {2, 11, 20, 11};
		private static final int[] TILE_Y = {12, 7, 12, 17};

		private boolean filled;

		FillTileGlyph(boolean filled)
		{
			this.filled = filled;
			setPreferredSize(new Dimension(22, 18));
			setOpaque(false);
		}

		void setFilled(boolean f)
		{
			filled = f;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			Polygon tile = new Polygon(TILE_X, TILE_Y, 4);
			if (filled)
			{
				g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.6f));
				g2.setColor(ColorScheme.BRAND_ORANGE);
				g2.fillPolygon(tile);
				g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1f));
			}
			g2.setStroke(new BasicStroke(1f));
			g2.setColor(ColorScheme.BRAND_ORANGE);
			g2.drawPolygon(tile);
			g2.dispose();
		}
	}

	// ─── HUD orientation glyph (3 dots horizontal ↔ vertical) ──────────────

	private static class HudOrientGlyph extends JPanel
	{
		private boolean vertical;

		HudOrientGlyph(boolean vertical)
		{
			this.vertical = vertical;
			setPreferredSize(new Dimension(20, 18));
			setOpaque(false);
		}

		void setVertical(boolean v)
		{
			vertical = v;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(ColorScheme.BRAND_ORANGE);
			int cx = getWidth() / 2;
			int cy = getHeight() / 2;
			final int dotR = 2;
			final int spacing = 5;
			for (int i = -1; i <= 1; i++)
			{
				int x = vertical ? cx               : cx + i * spacing;
				int y = vertical ? cy + i * spacing : cy;
				g2.fillOval(x - dotR, y - dotR, dotR * 2, dotR * 2);
			}
			g2.dispose();
		}
	}

	// ─── Card layout that sizes to the visible card only ──────────────────
	// Stock CardLayout reports max-of-all-cards for its preferred size, which
	// leaves dead space below the smaller (GRID) card. This subclass returns
	// only the currently-visible child's preferred/minimum size.

	private static class DynamicCardLayout extends CardLayout
	{
		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			return sizeOfVisible(parent, true);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return sizeOfVisible(parent, false);
		}

		private Dimension sizeOfVisible(Container parent, boolean preferred)
		{
			synchronized (parent.getTreeLock())
			{
				for (Component c : parent.getComponents())
				{
					if (c.isVisible())
					{
						Insets insets = parent.getInsets();
						Dimension d = preferred ? c.getPreferredSize() : c.getMinimumSize();
						return new Dimension(
							d.width  + insets.left + insets.right,
							d.height + insets.top  + insets.bottom);
					}
				}
				return preferred ? super.preferredLayoutSize(parent) : super.minimumLayoutSize(parent);
			}
		}
	}

	/**
	 * Small filled circle used in the Recorder row to mirror the on-HUD
	 * status dot — amber for ARM, red for ALWAYS, dim grey for OFF. Lets
	 * the user see at a glance what state they're configuring.
	 */
	private static final class RecordModeDot extends JComponent
	{
		private static final Color ARM_COLOR    = new Color(255, 180, 30);
		private static final Color ALWAYS_COLOR = new Color(220, 50,  50);
		private static final Color OFF_COLOR    = new Color(0x44, 0x44, 0x44);

		private RecordMode mode = RecordMode.OFF;

		RecordModeDot()
		{
			Dimension d = new Dimension(14, 14);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
			setOpaque(false);
		}

		void setMode(RecordMode m)
		{
			if (m != mode)
			{
				mode = m;
				repaint();
			}
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Color c;
			switch (mode)
			{
				case ARM:    c = ARM_COLOR;    break;
				case ALWAYS: c = ALWAYS_COLOR; break;
				default:     c = OFF_COLOR;    break;
			}
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(c);
			g2.fillOval(2, 3, 9, 9);
			g2.dispose();
		}
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.awt.Color;
import java.util.Set;
import lombok.Builder;

/**
 * Immutable view-state snapshot the plugin hands the panel to render itself.
 *
 * <p>Replaces the panel's pre-refactor habit of calling
 * {@code plugin.getConfig().xxx()} for every widget. The panel asks the
 * plugin once per refresh and renders from this snapshot — config remains
 * the persistence backend but never leaks into UI code, and one consistent
 * snapshot is read in one place instead of ~30 scattered config calls.
 *
 * <p>Includes {@link #effectiveCycleLength} so the panel doesn't have to
 * call back into the plugin for hotkey-override-aware cycle length.
 */
@Builder
final class ChromatickPanelSnapshot
{
	// ── Mode / palette ──────────────────────────────────────────────────
	final boolean staticMode;
	final PaletteMode paletteMode;
	final boolean sequentialFill;

	// ── Static-mode colors ──────────────────────────────────────────────
	final Color staticColor;
	final Color staticFillColor;

	// ── Tile appearance ─────────────────────────────────────────────────
	final double tileBorderWidth;
	final boolean enableFillColor;
	final int fillOpacity;
	final boolean drawBelowPlayer;

	// ── Display ─────────────────────────────────────────────────────────
	final DisplayMode displayMode;

	// ── HUD appearance ──────────────────────────────────────────────────
	final HudGlyph hudGlyph;
	final int hudScale;
	final int hudActiveOpacity;
	final int hudInactiveOpacity;
	final boolean hudBold;
	final int hudPop;
	final int hudSpacing;
	final boolean hudVertical;
	final HudAnchorTarget hudAnchorTarget;
	final int hudVerticalOffset;
	final int hudHorizontalOffset;
	final boolean hudCycleInPlace;

	// ── Recorder ────────────────────────────────────────────────────────
	final RecordMode recordMode;
	final IconPosition recordIconPosition;
	final int recordArmTicks;
	final Set<TickActionCategory> recordCategories;

	// ── Runtime-resolved (config + hotkey override) ─────────────────────
	final int effectiveCycleLength;

	/**
	 * Build a snapshot from the current config + already-resolved runtime
	 * values (effective cycle length, parsed category set). Kept as a
	 * single factory so the field-to-getter mapping lives in one place and
	 * is straightforward to unit-test.
	 */
	static ChromatickPanelSnapshot from(ChromatickConfig cfg, int effectiveCycleLength,
		Set<TickActionCategory> recordCategories)
	{
		return ChromatickPanelSnapshot.builder()
			.staticMode(cfg.staticMode())
			.paletteMode(cfg.paletteMode())
			.sequentialFill(cfg.sequentialFill())
			.staticColor(cfg.staticColor())
			.staticFillColor(cfg.staticFillColor())
			.tileBorderWidth(cfg.tileBorderWidth())
			.enableFillColor(cfg.enableFillColor())
			.fillOpacity(cfg.fillOpacity())
			.drawBelowPlayer(cfg.drawBelowPlayer())
			.displayMode(cfg.displayMode())
			.hudGlyph(cfg.hudGlyph())
			.hudScale(cfg.hudScale())
			.hudActiveOpacity(cfg.hudActiveOpacity())
			.hudInactiveOpacity(cfg.hudInactiveOpacity())
			.hudBold(cfg.hudBold())
			.hudPop(cfg.hudPop())
			.hudSpacing(cfg.hudSpacing())
			.hudVertical(cfg.hudVertical())
			.hudAnchorTarget(cfg.hudAnchorTarget())
			.hudVerticalOffset(cfg.hudVerticalOffset())
			.hudHorizontalOffset(cfg.hudHorizontalOffset())
			.hudCycleInPlace(cfg.hudCycleInPlace())
			.recordMode(cfg.recordMode())
			.recordIconPosition(cfg.recordIconPosition())
			.recordArmTicks(cfg.recordArmTicks())
			.recordCategories(recordCategories)
			.effectiveCycleLength(effectiveCycleLength)
			.build();
	}
}

