	void setRecordMode(RecordMode mode)
	{
		configManager.setConfiguration("chromatick", "recordMode", mode);
	}

	void setRecordIconPosition(IconPosition pos)
	{
		configManager.setConfiguration("chromatick", "recordIconPosition", pos);
	}

	void setRecordArmTicks(int ticks)
	{
		// Floor at 1; do not clamp against the effective cycle length here —
		// onGameTick clamps at the recorder feed site, so the persisted value
		// can stay at the user's intent (e.g. 8) even while a hotkey shrinks
		// the effective cycle (e.g. 4). When the cycle expands again the
		// persisted value comes back without rewriting config.
		configManager.setConfiguration("chromatick", "recordArmTicks", Math.max(1, ticks));
	}

	private void applyDisplayMode()
	{
		DisplayMode mode = config.displayMode();
		boolean tile = mode == DisplayMode.TILE || mode == DisplayMode.BOTH;
		boolean hud  = mode == DisplayMode.HUD  || mode == DisplayMode.BOTH;
		if (tile)
		{
			overlayManager.add(tileOverlay);
		}
		else
		{
			overlayManager.remove(tileOverlay);
		}
		if (hud)
		{
			overlayManager.add(hudOverlay);
			// On re-add, the overlay's stale lastSetLocation can mismatch the
			// framework's persisted preferred location, false-positiving the
			// next render's drag-detection check and flipping anchor to NONE.
			// Resetting the drag state lets the overlay re-anchor cleanly.
			hudOverlay.clearDragState();
		}
		else
		{
			overlayManager.remove(hudOverlay);
		}
	}

	/**
	 * Immutable view-state for the sidebar panel. Captures all settings + the
	 * runtime-resolved effective cycle length in a single read, so the panel
	 * doesn't reach into config directly.
	 */
	ChromatickPanelSnapshot snapshot()
	{
		return ChromatickPanelSnapshot.from(config, getEffectiveCycleLength(),
			enabledRecordCategories());
	}

	private Keybind getCycleHotkeyByLength(int n)
	{
		switch (n)
		{
			case 2: return config.cycle2Hotkey();
			case 3: return config.cycle3Hotkey();
			case 4: return config.cycle4Hotkey();
			case 5: return config.cycle5Hotkey();
			case 6: return config.cycle6Hotkey();
			case 7: return config.cycle7Hotkey();
			case 8: return config.cycle8Hotkey();
			case 9: return config.cycle9Hotkey();
			case 10: return config.cycle10Hotkey();
			default: return Keybind.NOT_SET;
		}
	}

	private Color getColorByIndex(int index)
	{
		Color[] palette = palettes.getCustomPaletteForCycle(getEffectiveCycleLength());
		return palette[index % palette.length];
	}
}

package com.chromatick;

import java.awt.Color;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;

/**
 * Transient runtime state for the cycle. Lives across game ticks but is not
 * persisted — config remains the persistence backend. Centralizing this state
 * here lets the plugin, overlays and tests reason about cycle/tick behavior
 * without each component owning its own slice.
 *
 * <p>Fields:
 * <ul>
 *   <li>{@code tickIndex} — current position in the color cycle (0-based).
 *   <li>{@code currentColor} — color resolved for the current tick.
 *   <li>{@code cycleLengthOverride} — hotkey-driven override of the configured
 *       cycle length; {@code -1} means "no override, use config".
 *   <li>{@code lastWorldPoint} — last observed player tile, used to detect
 *       movement for the tick recorder.
 * </ul>
 *
 * <p>All fields are {@code volatile} because they are written from more than
 * one thread: the game-tick + config-changed handlers run on the client
 * thread, while the key-listener callbacks (cycle-length override and reset)
 * dispatch on the Swing EDT. Without volatile the JVM could cache stale
 * values per thread.
 */
@Singleton
class ChromatickRuntimeState
{
	private volatile int tickIndex = 0;
	private volatile Color currentColor = Color.WHITE;
	private volatile int cycleLengthOverride = -1;
	private volatile WorldPoint lastWorldPoint = null;

	int getTickIndex()
	{
		return tickIndex;
	}

	void setTickIndex(int t)
	{
		this.tickIndex = t;
	}

	Color getCurrentColor()
	{
		return currentColor;
	}

	void setCurrentColor(Color c)
	{
		this.currentColor = c;
	}

	/** True when a hotkey has set a per-session cycle-length override. */
	boolean hasCycleLengthOverride()
	{
		return cycleLengthOverride > 0;
	}

	int getCycleLengthOverride()
	{
		return cycleLengthOverride;
	}

	void setCycleLengthOverride(int n)
	{
		this.cycleLengthOverride = n;
	}

	void clearCycleLengthOverride()
	{
		this.cycleLengthOverride = -1;
	}

	/**
	 * Resolve the effective cycle length: the hotkey override if active,
	 * otherwise the supplied configured value. Kept as a plain function so
	 * tests don't need to inject a config.
	 */
	int effectiveCycleLength(int configCycleLength)
	{
		return cycleLengthOverride > 0 ? cycleLengthOverride : configCycleLength;
	}

	WorldPoint getLastWorldPoint()
	{
		return lastWorldPoint;
	}

	void setLastWorldPoint(WorldPoint wp)
	{
		this.lastWorldPoint = wp;
	}

	/** Reset all transient state. Called from plugin startUp/shutDown. */
	void reset()
	{
		tickIndex = 0;
		currentColor = Color.WHITE;
		cycleLengthOverride = -1;
		lastWorldPoint = null;
	}
}

package com.chromatick;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JPanel;

/**
 * Discrete 12-hue × 3-ring colour wheel. Fills its entire component area — set
 * the preferred/maximum size from outside to control dimensions. The wheel is
 * always circular and centred; it uses the smaller of width/height as its
 * diameter so it adapts to any square or rectangular bounds.
 *
 * Geometry: uniform 30° wedges with a 2° visual gap, three concentric rings of
 * equal radial width separated by 2 px gaps, hub radius = 1 px.
 */
class ColorWheelPicker extends JPanel
{
	private static final int     HUES   = 12;
	private static final float   LINE_W = 2f;

	// (saturation %, lightness %) per ring, outer → inner
	private static final int[][] RINGS  = {
		{90, 50},
		{80, 66},
		{70, 82},
	};

	// Precomputed colours: cells[ring][hue]
	private final Color[][] cells = new Color[RINGS.length][HUES];

	private int selRing = -1;
	private int selHue  = -1;

	private final List<Consumer<Color>> listeners      = new ArrayList<>();
	private final List<Runnable>        commitListeners = new ArrayList<>();

	ColorWheelPicker()
	{
		for (int r = 0; r < RINGS.length; r++)
		{
			for (int h = 0; h < HUES; h++)
			{
				cells[r][h] = DiscretePalette.fromHSL(h * 30, RINGS[r][0], RINGS[r][1]);
			}
		}

		// Preferred is a hint; CardLayout stretches it to fill the container.
		setPreferredSize(new Dimension(212, 212));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				int[] cell = hitTest(e.getX(), e.getY());
				if (cell != null)
				{
					selRing = cell[0];
					selHue  = cell[1];
					repaint();
					Color c = cells[selRing][selHue];
					for (Consumer<Color> l : listeners)
					{
						l.accept(c);
					}
					for (Runnable r : commitListeners)
					{
						r.run();
					}
				}
			}
		});
	}

	void addColorListener(Consumer<Color> l)
	{
		listeners.add(l);
	}

	void addCommitListener(Runnable r)
	{
		commitListeners.add(r);
	}

	void setColorSilent(Color c)
	{
		int bestR = -1, bestH = -1;
		double bestDist = Double.MAX_VALUE;
		for (int r = 0; r < RINGS.length; r++)
		{
			for (int h = 0; h < HUES; h++)
			{
				int dr = c.getRed()   - cells[r][h].getRed();
				int dg = c.getGreen() - cells[r][h].getGreen();
				int db = c.getBlue()  - cells[r][h].getBlue();
				double d = dr * dr + dg * dg + db * db;
				if (d < bestDist)
				{
					bestDist = d;
					bestR = r;
					bestH = h;
				}
			}
		}
		selRing = bestR;
		selHue  = bestH;
		repaint();
	}

	Color getColor()
	{
		if (selRing < 0)
		{
			return Color.RED;
		}
		return cells[selRing][selHue];
	}

	// ─── Geometry helper ─────────────────────────────────────────────────
	//   Returns: [cx, cy, outerR, hubR, ringW]

	private float[] geom()
	{
		float size   = Math.min(getWidth(), getHeight());
		float cx     = getWidth()  / 2f;
		float cy     = getHeight() / 2f;
		float outerR = size / 2f - 2f;
		float hubR   = LINE_W / 2f;
		float ringW  = (outerR - hubR - LINE_W * (RINGS.length - 1)) / RINGS.length;
		return new float[]{cx, cy, outerR, hubR, ringW};
	}

	// ─── Hit test ─────────────────────────────────────────────────────────

	private int[] hitTest(int mx, int my)
	{
		float[] g     = geom();
		float   cx    = g[0], cy = g[1], outerR = g[2], hubR = g[3], ringW = g[4];
		float   dx    = mx - cx;
		float   dy    = my - cy;
		float   dist  = (float) Math.sqrt(dx * dx + dy * dy);
		if (dist < hubR || dist > outerR)
		{
			return null;
		}
		for (int r = 0; r < RINGS.length; r++)
		{
			float ro = outerR - r * (ringW + LINE_W);
			float ri = ro - ringW;
			if (dist <= ro && dist >= ri)
			{
				double screenDeg = Math.toDegrees(Math.atan2(dy, dx)) + 90;
				if (screenDeg < 0)
				{
					screenDeg += 360;
				}
				int h = (int) ((screenDeg + 15) % 360 / 30);
				if (h >= HUES)
				{
					h = HUES - 1;
				}
				return new int[]{r, h};
			}
		}
		return null;
	}

	// ─── Paint ────────────────────────────────────────────────────────────

	@Override
	protected void paintComponent(Graphics g)
	{
		if (getWidth() == 0 || getHeight() == 0)
		{
			return;
		}

		float[] geom  = geom();
		float   cx    = geom[0], cy = geom[1], outerR = geom[2], hubR = geom[3], ringW = geom[4];

		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_RENDERING,    RenderingHints.VALUE_RENDER_QUALITY);

		// Paint rings outer → inner, masking each inner radius after each ring
		for (int r = 0; r < RINGS.length; r++)
		{
			float ro = outerR - r * (ringW + LINE_W);
			float ri = ro - ringW;

			for (int h = 0; h < HUES; h++)
			{
				float javaCentre = 90f - h * 30f;
				float halfArc    = 14f;
				float startAngle = javaCentre + halfArc;
				float arcAngle   = -(halfArc * 2f);

				g2.setColor(cells[r][h]);
				int x = Math.round(cx - ro);
				int y = Math.round(cy - ro);
				int d = Math.round(ro * 2);
				g2.fillArc(x, y, d, d, Math.round(startAngle), Math.round(arcAngle));
			}

			// Mask inner gap
			if (ri > hubR)
			{
				g2.setColor(getBackground() != null ? getBackground() : new Color(0x242424));
				int x = Math.round(cx - ri);
				int y = Math.round(cy - ri);
				int d = Math.round(ri * 2);
				g2.fillOval(x, y, d, d);
			}
		}

		// Radial spokes
		Color bgColor = getBackground() != null ? getBackground() : new Color(0x242424);
		g2.setColor(bgColor);
		g2.setStroke(new BasicStroke(LINE_W, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
		for (int h = 0; h < HUES; h++)
		{
			double b  = Math.toRadians(h * 30.0 - 15.0);
			float  x1 = cx + hubR   * (float) Math.sin(b);
			float  y1 = cy - hubR   * (float) Math.cos(b);
			float  x2 = cx + outerR * (float) Math.sin(b);
			float  y2 = cy - outerR * (float) Math.cos(b);
			g2.drawLine(Math.round(x1), Math.round(y1), Math.round(x2), Math.round(y2));
		}

		// Concentric ring separators
		g2.setStroke(new BasicStroke(LINE_W));
		for (int r = 0; r < RINGS.length - 1; r++)
		{
			float ro   = outerR - r * (ringW + LINE_W);
			float ri   = ro - ringW;
			float sepR = ri - LINE_W / 2f;
			g2.setColor(bgColor);
			g2.drawOval(Math.round(cx - sepR), Math.round(cy - sepR),
				Math.round(sepR * 2), Math.round(sepR * 2));
		}

		// Outer boundary
		g2.setStroke(new BasicStroke(LINE_W * 2));
		g2.setColor(bgColor);
		g2.drawOval(Math.round(cx - outerR), Math.round(cy - outerR),
			Math.round(outerR * 2), Math.round(outerR * 2));

		// Hub
		g2.setColor(bgColor);
		g2.fillOval(Math.round(cx - hubR), Math.round(cy - hubR),
			Math.round(hubR * 2 + 1), Math.round(hubR * 2 + 1));

		g2.dispose();
	}
}

package com.chromatick;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JPanel;

/**
 * 6-column × 5-row HSL colour grid (30 cells). Row 0 = six neutrals (white→black);
 * rows 1–4 = six hue columns at four lightness steps. Generated from HSL so the
 * palette matches the V1+ Refined design spec exactly.
 *
 * Clicking any cell fires listeners and commits immediately.
 */
class DiscretePalette extends JPanel
{
	private static final int COLS = 6;
	private static final int ROWS = 5;
	private static final int CELL_H = 20;
	private static final int CELL_GAP = 3;
	private static final int PADDING = 4;

	// Row 0: neutral greys, white→black
	private static final int[] NEUTRAL_RGB = {
		0xFFFFFF, 0xCCCCCC, 0x999999, 0x666666, 0x333333, 0x000000
	};

	// Hue angles (degrees) for the 6 hue columns
	private static final int[] HUE_ANGLES = {0, 28, 50, 130, 215, 285};

	// (saturation%, lightness%) per row; rows 1–4 go light→dark
	private static final int[][] HSL_ROWS = {
		{95, 82},
		{85, 68},
		{75, 52},
		{65, 36},
	};

	// Precomputed cell colours [row][col]
	private final Color[][] cells = new Color[ROWS][COLS];

	// Currently highlighted cell (null if none)
	private Color selected;

	private final List<Consumer<Color>> listeners = new ArrayList<>();
	private final List<Runnable> commitListeners = new ArrayList<>();

	DiscretePalette()
	{
		// Build the colour grid
		for (int col = 0; col < COLS; col++)
		{
			cells[0][col] = new Color(NEUTRAL_RGB[col]);
		}
		for (int row = 0; row < HSL_ROWS.length; row++)
		{
			for (int col = 0; col < COLS; col++)
			{
				cells[row + 1][col] = fromHSL(HUE_ANGLES[col], HSL_ROWS[row][0], HSL_ROWS[row][1]);
			}
		}

		int prefH = ROWS * CELL_H + (ROWS - 1) * CELL_GAP + PADDING * 2;
		setPreferredSize(new Dimension(212, prefH));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, prefH));
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				Color c = hitTest(e.getX(), e.getY());
				if (c != null)
				{
					selected = c;
					repaint();
					for (Consumer<Color> l : listeners)
					{
						l.accept(c);
					}
					for (Runnable r : commitListeners)
					{
						r.run();
					}
				}
			}
		});
	}

	void addColorListener(Consumer<Color> l)
	{
		listeners.add(l);
	}

	void addCommitListener(Runnable r)
	{
		commitListeners.add(r);
	}

	/** Highlight the closest grid cell to c without firing listeners. */
	void setColorSilent(Color c)
	{
		Color best = null;
		double bestDist = Double.MAX_VALUE;
		for (Color[] row : cells)
		{
			for (Color cell : row)
			{
				double d = colorDist(c, cell);
				if (d < bestDist)
				{
					bestDist = d;
					best = cell;
				}
			}
		}
		selected = best;
		repaint();
	}

	private Color hitTest(int mx, int my)
	{
		int availW = getWidth() - PADDING * 2;
		float step = (float) (availW - (COLS - 1) * CELL_GAP) / COLS;

		for (int row = 0; row < ROWS; row++)
		{
			for (int col = 0; col < COLS; col++)
			{
				int x = PADDING + Math.round(col * (step + CELL_GAP));
				int y = PADDING + row * (CELL_H + CELL_GAP);
				if (mx >= x && mx < x + step && my >= y && my < y + CELL_H)
				{
					return cells[row][col];
				}
			}
		}
		return null;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int availW = getWidth() - PADDING * 2;
		float step = (float) (availW - (COLS - 1) * CELL_GAP) / COLS;

		for (int row = 0; row < ROWS; row++)
		{
			for (int col = 0; col < COLS; col++)
			{
				Color c = cells[row][col];
				int x = PADDING + Math.round(col * (step + CELL_GAP));
				int y = PADDING + row * (CELL_H + CELL_GAP);
				int w = Math.round(step);

				g2.setColor(c);
				g2.fillRoundRect(x, y, w, CELL_H, 4, 4);
			}
		}

		g2.dispose();
	}

	// ─── Shared HSL → Color helper (also used by ColorWheelPicker) ────────

	/** Convert HSL (h: 0–360, s: 0–100, l: 0–100) to a {@link Color}. */
	static Color fromHSL(int h, int s, int l)
	{
		float hf = h;
		float sf = s / 100f;
		float lf = l / 100f;
		float c = (1f - Math.abs(2f * lf - 1f)) * sf;
		float x = c * (1f - Math.abs(hf / 60f % 2f - 1f));
		float m = lf - c / 2f;
		float r, gr, b;
		if (hf < 60)       { r = c;  gr = x;  b = 0;  }
		else if (hf < 120) { r = x;  gr = c;  b = 0;  }
		else if (hf < 180) { r = 0;  gr = c;  b = x;  }
		else if (hf < 240) { r = 0;  gr = x;  b = c;  }
		else if (hf < 300) { r = x;  gr = 0;  b = c;  }
		else               { r = c;  gr = 0;  b = x;  }
		return new Color(
			Math.min(255, Math.round((r  + m) * 255)),
			Math.min(255, Math.round((gr + m) * 255)),
			Math.min(255, Math.round((b  + m) * 255))
		);
	}

	private static double colorDist(Color a, Color b)
	{
		int dr = a.getRed()   - b.getRed();
		int dg = a.getGreen() - b.getGreen();
		int db = a.getBlue()  - b.getBlue();
		return dr * dr + dg * dg + db * db;
	}
}

package com.chromatick;

/**
 * Centralized enum types for the ChromaTick package. Nested inside a
 * public holder so RuneLite's {@code ConfigManager} dynamic proxy can
 * see them (a proxy implementing {@link ChromatickConfig} is generated
 * in a context that can't access package-private types in this package
 * — it throws {@code IllegalAccessError} on any config getter that
 * returns one). With the holder class public and the nested enums
 * public, the proxy resolves the return types via standard reflection.
 *
 * <p>Call sites can import the nested types via
 * {@code import com.chromatick.Enums.*;} (or one at a time) so the
 * unqualified names {@code DisplayMode}, {@code HudGlyph} etc. still
 * work everywhere.
 */
public final class Enums
{
	private Enums()
	{
		// Utility holder; never instantiated.
	}

	/** Where the tick visualization renders. */
	public enum DisplayMode
	{
		TILE,
		HUD,
		BOTH
	}

	/** Where the HUD anchors to the player model. */
	public enum HudAnchorTarget
	{
		HEAD,
		FEET,
		NONE
	}

	/** Glyph style inside the HUD frame. */
	public enum HudGlyph
	{
		DOTS,
		NUMBERS
	}

	/** Where the recorded icons render relative to the HUD glyph row. */
	public enum IconPosition
	{
		ABOVE,
		BELOW
	}

	/** Palette-picker variant in the sidebar panel. */
	public enum PaletteMode
	{
		GRID,
		WHEEL
	}

	/**
	 * State of the per-tick recorder.
	 *
	 * <p>OFF — no recording, no display.
	 * <br>ARM — recorder waits for the player to move, then captures the
	 * movement tick plus a configurable trailing window.
	 * <br>ALWAYS — every tick is captured (subsequent cycles overwrite older
	 * data at the same tick index).
	 */
	public enum RecordMode
	{
		OFF,
		ARM,
		ALWAYS;

		/** Advance to the next mode in OFF → ARM → ALWAYS → OFF order. */
		public RecordMode next()
		{
			RecordMode[] values = values();
			return values[(ordinal() + 1) % values.length];
		}
	}

	/**
	 * What kind of player action a {@link TickActionEvent} represents. The
	 * recorder filters captured events by the user's selected categories;
	 * the icon resolver maps each category to its sprite or primitive glyph.
	 *
	 * <p>Declaration order is also default render priority when multiple
	 * categories fire on the same tick — earlier categories win when slot
	 * space is limited. ITEM_USE outranks RED/YELLOW because a "use knife on
	 * log" click is more informative than "you clicked yellow this tick".
	 */
	public enum TickActionCategory
	{
		/** Active Protect-from-X prayer this tick. */
		PROTECTION_PRAYER,
		/** Use-item-on-X click. Carries source + target item IDs. */
		ITEM_USE,
		/** Attack-type click — cursor was red when the player clicked. */
		RED_CLICK,
		/** Any other click — cursor was yellow. Includes walk-here. */
		YELLOW_CLICK
	}
}

package com.chromatick;

import com.chromatick.Enums.*;

/**
 * Pure layout math for the HUD metronome bar. Computes cell/glyph sizing,
 * spacing and bounding dimensions from raw config inputs so the geometry
 * can be unit-tested without a real overlay/render context.
 *
 * <p>Optionally reserves an icon band alongside the glyph row, used by the
 * per-tick recorder. The band is only present in row layouts (i.e. not
 * cycle-in-place) and uses the <em>non-popped</em> base glyph size as its
 * cross-axis thickness — independent of {@code hudPop}, so the lane stays
 * tight even when the active glyph balloons.
 *
 * <p>When {@code comboLayout} is true, a <em>second</em> icon band is
 * reserved alongside the primary band on the same side of the glyph row.
 * Combo events (ITEM_USE source + target) render their primary in the
 * inner band (adjacent to the glyph row) and the secondary in the outer
 * band (further from it). Non-combo slots in a combo-capable layout
 * simply leave the secondary band empty. The "same side" placement keeps
 * the {@link IconPosition} contract intuitive: choosing ABOVE / BELOW
 * dictates where <em>all</em> icons live, never splitting them across
 * the glyph row.
 *
 * <p>Orientation:
 * <ul>
 *   <li>Horizontal row: icons go ABOVE or BELOW the glyph row.
 *   <li>Vertical column: icons go to the LEFT (ABOVE) or RIGHT (BELOW) of
 *       the glyph column.
 * </ul>
 */
final class HudLayout
{
	static final int BASE_GLYPH_PX = 10;
	/** 1px margin around the row to leave room for the drop shadow. */
	static final int MARGIN_PX = 2;

	final int cellSize;
	final int baseGlyph;
	final int gap;
	final int slots;
	final boolean vertical;
	final int totalWidth;
	final int totalHeight;

	/** True when an icon band is present (and large enough to render). */
	final boolean showIcons;
	/** True when a second icon band is reserved alongside the primary, same side of the glyph row. */
	final boolean comboLayout;
	/** Cross-axis thickness of one icon band in px; 0 when {@link #showIcons} is false. */
	final int iconBandPx;
	final IconPosition iconPosition;

	private HudLayout(int cellSize, int baseGlyph, int gap, int slots,
		boolean vertical, int totalWidth, int totalHeight,
		boolean showIcons, boolean comboLayout, int iconBandPx, IconPosition iconPosition)
	{
		this.cellSize = cellSize;
		this.baseGlyph = baseGlyph;
		this.gap = gap;
		this.slots = slots;
		this.vertical = vertical;
		this.totalWidth = totalWidth;
		this.totalHeight = totalHeight;
		this.showIcons = showIcons;
		this.comboLayout = comboLayout;
		this.iconBandPx = iconBandPx;
		this.iconPosition = iconPosition;
	}

	/** Bar without an icon band — original geometry. */
	static HudLayout compute(int scalePct, int popPct, int spacingPx,
		int cycleLength, boolean vertical, boolean cycleInPlace)
	{
		return compute(scalePct, popPct, spacingPx, cycleLength,
			vertical, cycleInPlace, false, IconPosition.ABOVE, false);
	}

	/** Bar with an optional icon band alongside the glyph row, no combo support. */
	static HudLayout compute(int scalePct, int popPct, int spacingPx,
		int cycleLength, boolean vertical, boolean cycleInPlace,
		boolean wantIcons, IconPosition iconPosition)
	{
		return compute(scalePct, popPct, spacingPx, cycleLength,
			vertical, cycleInPlace, wantIcons, iconPosition, false);
	}

	/**
	 * Bar with an optional icon band, optionally combo-capable.
	 *
	 * <p>The icon band is only honored in row layouts — cycle-in-place mode
	 * forces {@code showIcons=false} regardless of the {@code wantIcons}
	 * argument (a single glyph has no timeline to align icons against).
	 * Combo layout requires {@code showIcons} to be effective — when icons
	 * are off, the combo flag is moot.
	 */
	static HudLayout compute(int scalePct, int popPct, int spacingPx,
		int cycleLength, boolean vertical, boolean cycleInPlace,
		boolean wantIcons, IconPosition iconPosition, boolean comboCapable)
	{
		final float scale = clamp(scalePct, 50, 400) / 100f;
		final float popFactor = 1f + clamp(popPct, 0, 200) / 100f;
		final float baseGlyphF = BASE_GLYPH_PX * scale;
		final int baseGlyph = Math.max(6, Math.round(baseGlyphF));
		final int cellSize = Math.max(baseGlyph, Math.round(baseGlyphF * popFactor));
		final int gap = Math.round(clamp(spacingPx, -10, 10) * scale);

		final int slots = cycleInPlace ? 1 : cycleLength;
		final int mainAxisLen = Math.max(cellSize, slots * cellSize + (slots - 1) * gap);

		// Icons need a timeline to align against — disable in cycle-in-place mode.
		final boolean showIcons = wantIcons && !cycleInPlace;
		final boolean comboLayout = showIcons && comboCapable;
		// Lane thickness tracks the non-popped glyph size, not the cell size,
		// so the recorder lane stays tight when hudPop inflates the active
		// glyph's cell.
		final int iconBandPx = showIcons ? baseGlyph : 0;
		final int totalIconPx = iconBandPx * (comboLayout ? 2 : (showIcons ? 1 : 0));

		final int crossAxisLen = cellSize + totalIconPx;
		final int totalW = (vertical ? crossAxisLen : mainAxisLen) + 2 * MARGIN_PX;
		final int totalH = (vertical ? mainAxisLen : crossAxisLen) + 2 * MARGIN_PX;

		return new HudLayout(cellSize, baseGlyph, gap, slots, vertical,
			totalW, totalH, showIcons, comboLayout, iconBandPx, iconPosition);
	}

	/** X center of slot {@code k} relative to the overlay's top-left. */
	int cellCenterX(int k)
	{
		int cellOffset = vertical ? 0 : k * (cellSize + gap);
		// Vertical mode shifts the glyph column right when icon bands sit on
		// the left (iconPosition=ABOVE). Combo doubles the shift since both
		// bands now stack on the same side as the primary.
		int iconShift = (showIcons && vertical && iconPosition == IconPosition.ABOVE)
			? iconBandPx * (comboLayout ? 2 : 1) : 0;
		return MARGIN_PX + iconShift + cellOffset + cellSize / 2;
	}

	/** Y center of slot {@code k} relative to the overlay's top-left. */
	int cellCenterY(int k)
	{
		int cellOffset = vertical ? k * (cellSize + gap) : 0;
		int iconShift = (showIcons && !vertical && iconPosition == IconPosition.ABOVE)
			? iconBandPx * (comboLayout ? 2 : 1) : 0;
		return MARGIN_PX + iconShift + cellOffset + cellSize / 2;
	}

	/**
	 * Glyph diameter (px). The active glyph expands to fill the cell so the
	 * pop effect is visible; inactive glyphs sit at the base size so the row
	 * stays visually quiet.
	 */
	int glyphSize(boolean active)
	{
		return active ? Math.max(baseGlyph, cellSize - 2) : baseGlyph;
	}

	/** X center of the primary icon for slot {@code k}, or -1 when no icon band is shown. */
	int iconCenterX(int k)
	{
		if (!showIcons)
		{
			return -1;
		}
		if (vertical)
		{
			// Primary column sits directly adjacent to the glyph column.
			// In combo + ABOVE, the secondary band stacks further left, so
			// primary's center moves right by one band.
			return iconPosition == IconPosition.ABOVE
				? MARGIN_PX + (comboLayout ? iconBandPx : 0) + iconBandPx / 2
				: MARGIN_PX + cellSize + iconBandPx / 2;
		}
		return cellCenterX(k);
	}

	/** Y center of the primary icon for slot {@code k}, or -1 when no icon band is shown. */
	int iconCenterY(int k)
	{
		if (!showIcons)
		{
			return -1;
		}
		if (vertical)
		{
			return cellCenterY(k);
		}
		// Primary band sits directly adjacent to the glyph row.
		return iconPosition == IconPosition.ABOVE
			? MARGIN_PX + (comboLayout ? iconBandPx : 0) + iconBandPx / 2
			: MARGIN_PX + cellSize + iconBandPx / 2;
	}

	/**
	 * X center of the secondary (combo) icon for slot {@code k}, or -1 when
	 * the layout isn't combo-capable. Lives in the outer band on the same
	 * side of the glyph row as the primary.
	 */
	int comboIconCenterX(int k)
	{
		if (!comboLayout)
		{
			return -1;
		}
		if (vertical)
		{
			// Secondary column sits in the outer band, further from the glyph
			// column than the primary.
			return iconPosition == IconPosition.ABOVE
				? MARGIN_PX + iconBandPx / 2
				: MARGIN_PX + cellSize + iconBandPx + iconBandPx / 2;
		}
		return cellCenterX(k);
	}

	/** Y center of the secondary (combo) icon for slot {@code k}, or -1 when not combo-capable. */
	int comboIconCenterY(int k)
	{
		if (!comboLayout)
		{
			return -1;
		}
		if (vertical)
		{
			return cellCenterY(k);
		}
		return iconPosition == IconPosition.ABOVE
			? MARGIN_PX + iconBandPx / 2
			: MARGIN_PX + cellSize + iconBandPx + iconBandPx / 2;
	}

	private static int clamp(int v, int lo, int hi)
	{
		return Math.max(lo, Math.min(hi, v));
	}
}

package com.chromatick;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.awt.Color;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
