/**
 * Storage and retrieval of the per-cycle color palettes. Holds the static
 * default {@link #PALETTES} table (perceptually-optimal n-color palettes for
 * cycles 2..10) and reads/writes the user's custom palette overrides via
 * {@link ConfigManager}.
 *
 * <p>Custom palettes are stored as JSON arrays of RGB ints keyed
 * {@code customPalette2}..{@code customPalette10}. A missing or unparseable
 * key falls back to the default palette for that cycle length.
 */
@Slf4j
@Singleton
class PaletteService
{
	static final int MIN_CYCLE = 2;
	static final int MAX_CYCLE = 10;

	private static final String CONFIG_GROUP = "chromatick";
	static final String CUSTOM_PALETTE_PREFIX = "customPalette";
	private static final Type PALETTE_TYPE = new TypeToken<List<Integer>>(){}.getType();

	// PALETTES[n] = the perceptually-optimal n-color palette, indexed by cycle length.
	// Computed using OKLab perceptual color space with a greedy farthest-point algorithm.
	// Each palette has its colors maximally distinct and spread evenly around the hue wheel.
	static final Color[][] PALETTES = {
		null, // index 0 unused
		null, // index 1 unused
		{
			// cycle 2
			new Color(255, 64, 64),  // red
			new Color(64, 224, 224), // cyan
		},
		{
			// cycle 3
			new Color(255, 64, 64),  // red
			new Color(255, 224, 32), // yellow
			new Color(64, 128, 255), // blue
		},
		{
			// cycle 4
			new Color(255, 64, 64),  // red
			new Color(255, 224, 32), // yellow
			new Color(96, 224, 96),  // green
			new Color(64, 128, 255), // blue
		},
		{
			// cycle 5
			new Color(255, 64, 64),  // red
			new Color(255, 160, 32), // orange
			new Color(255, 224, 32), // yellow
			new Color(96, 224, 96),  // green
			new Color(64, 128, 255), // blue
		},
		{
			// cycle 6
			new Color(255, 64, 64),  // red
			new Color(255, 160, 32), // orange
			new Color(255, 224, 32), // yellow
			new Color(96, 224, 96),  // green
			new Color(64, 224, 224), // cyan
			new Color(64, 128, 255), // blue
		},
		{
			// cycle 7
			new Color(255, 64, 64),  // red
			new Color(255, 160, 32), // orange
			new Color(255, 224, 32), // yellow
			new Color(96, 224, 96),  // green
			new Color(64, 224, 224), // cyan
			new Color(64, 128, 255), // blue
			new Color(128, 96, 255), // violet
		},
		{
			// cycle 8
			new Color(255, 64, 64),  // red
			new Color(255, 160, 32), // orange
			new Color(255, 224, 32), // yellow
			new Color(96, 224, 96),  // green
			new Color(64, 224, 224), // cyan
			new Color(64, 128, 255), // blue
			new Color(128, 96, 255), // indigo
			new Color(224, 96, 224), // magenta
		},
		{
			// cycle 9
			new Color(255, 64, 64),  // red
			new Color(255, 160, 32), // orange
			new Color(255, 224, 32), // yellow
			new Color(192, 224, 32), // yellow-green
			new Color(64, 224, 64),  // green
			new Color(64, 224, 224), // cyan
			new Color(64, 128, 255), // blue
			new Color(160, 64, 255), // purple
			new Color(224, 64, 192), // magenta
		},
		{
			// cycle 10
			new Color(255, 64, 64),  // red
			new Color(255, 144, 32), // orange
			new Color(255, 192, 32), // amber
			new Color(255, 224, 32), // yellow
			new Color(192, 224, 32), // yellow-green
			new Color(64, 224, 64),  // green
			new Color(64, 224, 224), // cyan
			new Color(64, 128, 255), // blue
			new Color(128, 64, 255), // purple
			new Color(224, 64, 192), // magenta
		},
	};

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	PaletteService(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/**
	 * Resolve the palette for {@code cycleLength}, layering the user's custom
	 * overrides on top of {@link #PALETTES}. Returns a fresh array — safe for
	 * the caller to mutate.
	 */
	Color[] getCustomPaletteForCycle(int cycleLength)
	{
		int n = clampCycle(cycleLength);
		Color[] defaults = PALETTES[n];
		String json = configManager.getConfiguration(CONFIG_GROUP, CUSTOM_PALETTE_PREFIX + n);
		if (json == null || json.isEmpty())
		{
			return defaults.clone();
		}
		try
		{
			List<Integer> rgbs = gson.fromJson(json, PALETTE_TYPE);
			Color[] result = new Color[n];
			for (int i = 0; i < n; i++)
			{
				if (rgbs != null && i < rgbs.size() && rgbs.get(i) != null)
				{
					result[i] = new Color(rgbs.get(i), true);
				}
				else
				{
					result[i] = defaults[i];
				}
			}
			return result;
		}
		catch (Exception e)
		{
			log.debug("Failed to parse custom palette for cycle {}: {}", n, e.toString());
			return defaults.clone();
		}
	}

	void setCustomPaletteColor(int cycleLength, int index, Color color)
	{
		int n = clampCycle(cycleLength);
		if (index < 0 || index >= n)
		{
			return;
		}
		Color[] current = getCustomPaletteForCycle(n);
		current[index] = color;
		List<Integer> rgbs = new ArrayList<>(n);
		for (Color c : current)
		{
			rgbs.add(c.getRGB());
		}
		configManager.setConfiguration(CONFIG_GROUP, CUSTOM_PALETTE_PREFIX + n, gson.toJson(rgbs));
	}

	void resetCustomPaletteForCycle(int cycleLength)
	{
		int n = clampCycle(cycleLength);
		configManager.unsetConfiguration(CONFIG_GROUP, CUSTOM_PALETTE_PREFIX + n);
	}

	static int clampCycle(int n)
	{
		return Math.max(MIN_CYCLE, Math.min(MAX_CYCLE, n));
	}

	/**
	 * Extract the cycle-length integer from a {@code customPaletteN} config
	 * key. Returns -1 for any suffix that isn't a parseable integer; callers
	 * rely on the sentinel rather than catching exceptions.
	 */
	static int parsePaletteKey(String key)
	{
		try
		{
			return Integer.parseInt(key.substring(CUSTOM_PALETTE_PREFIX.length()));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

package com.chromatick;

import java.awt.Color;
import java.awt.image.BufferedImage;

/**
 * What the HUD should draw for one recorded event. Three shapes:
 *
 * <ul>
 *   <li><b>Single sprite</b> — {@code sprite} non-null, the rest null.
 *       Prayer protection icons, single-item item-use, etc.
 *   <li><b>Combo</b> — {@code sprite} + {@code secondarySprite} both
 *       non-null. ITEM_USE source + target rendered in stacked icon
 *       lanes on the same side of the glyph row (primary adjacent to
 *       the glyphs, secondary in the outer band).
 *   <li><b>Primitive dot</b> — {@code primitiveColor} non-null, sprites
 *       null. Fallback / no-sprite categories (e.g. cross-sprites not
 *       loaded yet).
 * </ul>
 *
 * <p>Exactly one of these shapes applies per instance; the HUD branches
 * on which field is set.
 */
final class RecordedIcon
{
	final BufferedImage sprite;
	final BufferedImage secondarySprite;
	final Color primitiveColor;

	private RecordedIcon(BufferedImage sprite, BufferedImage secondarySprite, Color primitiveColor)
	{
		this.sprite = sprite;
		this.secondarySprite = secondarySprite;
		this.primitiveColor = primitiveColor;
	}

	/** Render the given sprite at the icon slot. */
	static RecordedIcon sprite(BufferedImage sprite)
	{
		return new RecordedIcon(sprite, null, null);
	}

	/**
	 * Render two sprites — primary in the inner band (adjacent to the glyph
	 * row), secondary in the outer band on the same side. Used by ITEM_USE
	 * when both source + target item IDs were captured.
	 */
	static RecordedIcon combo(BufferedImage primary, BufferedImage secondary)
	{
		return new RecordedIcon(primary, secondary, null);
	}

	/** Render a filled colored disc at the icon slot. */
	static RecordedIcon dot(Color color)
	{
		return new RecordedIcon(null, null, color);
	}

	/** True when both sprites are present and the HUD should render combo geometry. */
	boolean isCombo()
	{
		return sprite != null && secondarySprite != null;
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.awt.Color;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Prayer;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;

/**
 * Resolves a per-tick recorded payload to the sprite(s) the HUD timeline
 * should draw. Owns its own sprite cache so the HUD overlay only deals in
 * "give me an icon for this tick" — sprite loading, sprite identity, and
 * payload→icon arbitration all live here.
 *
 * <p>Entry points: {@link #iconFor(RecordedTick)} for legacy prayer-only
 * payloads and {@link #iconFor(TickActionEvent)} for the generic action
 * pipeline. Sprite loading, sprite identity, and payload→icon arbitration
 * all live here so the overlay can stay focused on geometry.
 *
 * <p>Thread model: the SpriteManager async callbacks fire from a background
 * thread; the HUD overlay reads sprites from the client (render) thread.
 * The cache fields are {@code volatile} so the render thread sees the
 * callback's write without explicit synchronisation.
 */
@Singleton
class RecordedIconResolver
{
	// Cursor colors used when the live cross sprites aren't loaded yet
	// (early frames before Client.getCrossSprites() returns a populated
	// array). Tuned bright so the fallback dots stay legible.
	private static final Color RED_CLICK_FALLBACK    = new Color(0xE8, 0x35, 0x35);
	private static final Color YELLOW_CLICK_FALLBACK = new Color(0xF5, 0xC5, 0x2A);

	// Fallback color for ITEM_USE when the source-item lookup fails (no
	// selected widget, no item ID, etc.). A muted cyan — distinct from
	// red/yellow without clashing.
	private static final Color ITEM_USE_FALLBACK = new Color(0x40, 0xC8, 0xA0);

	// Indices into Client.getCrossSprites(). OSRS exposes 8 frames total —
	// frames 0-3 are the yellow click animation, frames 4-7 are red.
	// Pick mid-animation (largest X) for the HUD's static glyph.
	private static final int YELLOW_CROSS_INDEX = 2;
	private static final int RED_CROSS_INDEX    = 6;

	private final Client client;
	private final SpriteManager spriteManager;
	private final ItemManager itemManager;

	private volatile BufferedImage spriteMelee;
	private volatile BufferedImage spriteMissiles;
	private volatile BufferedImage spriteMagic;
	private volatile BufferedImage spriteInventory;
	private boolean requested = false;

	// Cross-sprite cache. Populated lazily on first render that needs them
	// — the array isn't always available at plugin startUp.
	private volatile BufferedImage crossYellow;
	private volatile BufferedImage crossRed;

	@Inject
	RecordedIconResolver(Client client, SpriteManager spriteManager, ItemManager itemManager)
	{
		this.client = client;
		this.spriteManager = spriteManager;
		this.itemManager = itemManager;
	}

	/**
	 * Trigger the async sprite load. Idempotent — the first call kicks off
	 * the SpriteManager fetches, subsequent calls are no-ops. Cheap enough
	 * to call once per render frame.
	 *
	 * <p>Loads three protect-prayer sprites (HUD rendering) and the
	 * inventory tab sprite (panel category-pill icon for ITEM_USE).
	 */
	void ensureLoaded()
	{
		if (requested)
		{
			return;
		}
		requested = true;
		spriteManager.getSpriteAsync(SpriteID.Prayeron.PROTECT_FROM_MELEE,    0, img -> spriteMelee    = img);
		spriteManager.getSpriteAsync(SpriteID.Prayeron.PROTECT_FROM_MISSILES, 0, img -> spriteMissiles = img);
		spriteManager.getSpriteAsync(SpriteID.Prayeron.PROTECT_FROM_MAGIC,    0, img -> spriteMagic    = img);
		spriteManager.getSpriteAsync(SpriteID.SideIcons.INVENTORY,            0, img -> spriteInventory = img);
	}

	/**
	 * Representative icon for a category, used by the settings panel's
	 * capture-category pill row. Returns {@code null} when the sprite
	 * hasn't loaded yet — callers should show a placeholder and rely on
	 * subsequent repaints picking up the loaded image.
	 *
	 * <p>Distinct from the per-event HUD rendering: ITEM_USE in the HUD
	 * draws the actual source item sprite (knife, herb, etc.), but the
	 * panel pill needs a stable abstract icon — the inventory backpack.
	 */
	BufferedImage categoryIcon(TickActionCategory category)
	{
		ensureLoaded();
		switch (category)
		{
			case PROTECTION_PRAYER:
				return spriteMelee;
			case ITEM_USE:
				return spriteInventory;
			case RED_CLICK:
				if (crossRed == null)
				{
					crossRed = loadCrossSprite(RED_CROSS_INDEX);
				}
				return crossRed;
			case YELLOW_CLICK:
				if (crossYellow == null)
				{
					crossYellow = loadCrossSprite(YELLOW_CROSS_INDEX);
				}
				return crossYellow;
			default:
				return null;
		}
	}

	/**
	 * Resolve the icon to render for a recorded tick. Walks the event
	 * list in insertion order — the plugin's {@code buildTickEvents} adds
	 * prayer events first, then the captured click, so this naturally
	 * yields the rendering priority:
	 * <ol>
	 *   <li>PROTECTION_PRAYER always wins when one is active and the
	 *       prayer sprite has loaded.
	 *   <li>ITEM_USE or YELLOW/RED click otherwise. The capture service can
	 *       resolve multiple acknowledged intents on one tick; this resolver
	 *       shows the first renderable event in recorded insertion order.
	 * </ol>
	 * Returns {@code null} when nothing was recorded or no event yet has
	 * a renderable icon (e.g. sprite still loading — render falls back to
	 * the next event, or nothing if none).
	 */
	RecordedIcon iconFor(RecordedTick recorded)
	{
		if (recorded.isEmpty())
		{
			return null;
		}
		for (TickActionEvent event : recorded.actions())
		{
			RecordedIcon icon = iconFor(event);
			if (icon != null)
			{
				return icon;
			}
		}
		return null;
	}

	private RecordedIcon iconFor(TickActionEvent event)
	{
		switch (event.category())
		{
			case PROTECTION_PRAYER:
				BufferedImage prayerSprite = prayerSprite(event.primaryId());
				return prayerSprite == null ? null : RecordedIcon.sprite(prayerSprite);
			case ITEM_USE:
				return itemUseIcon(event);
			case RED_CLICK:
				return crossIcon(true);
			case YELLOW_CLICK:
				return crossIcon(false);
			default:
				return null;
		}
	}

	/**
	 * Return the cached cross sprite (yellow or red). Pulls from
	 * {@link Client#getCrossSprites()} on first call and converts the
	 * native {@link SpritePixels} to a {@link BufferedImage}; cached for
	 * the remainder of the session. Falls back to a colored dot if the
	 * sprite array isn't populated yet — the client doesn't always have
	 * it ready immediately at plugin startup.
	 */
	private RecordedIcon crossIcon(boolean red)
	{
		BufferedImage cached = red ? crossRed : crossYellow;
		if (cached == null)
		{
			cached = loadCrossSprite(red ? RED_CROSS_INDEX : YELLOW_CROSS_INDEX);
			if (cached != null)
			{
				if (red)
				{
					crossRed = cached;
				}
				else
				{
					crossYellow = cached;
				}
			}
		}
		if (cached != null)
		{
			return RecordedIcon.sprite(cached);
		}
		return RecordedIcon.dot(red ? RED_CLICK_FALLBACK : YELLOW_CLICK_FALLBACK);
	}

	private BufferedImage loadCrossSprite(int index)
	{
		SpritePixels[] sprites = client.getCrossSprites();
		if (sprites == null || index < 0 || index >= sprites.length || sprites[index] == null)
		{
			return null;
		}
		return sprites[index].toBufferedImage();
	}

	/**
	 * Render an ITEM_USE event:
	 * <ul>
	 *   <li>Both source + target known → combo (two sprites stacked in the
	 *       icon band on the same side of the glyph row — knife + log,
	 *       herb + tar, etc.).
	 *   <li>Source only known → single sprite of the source item.
	 *   <li>Neither known (selection lookup failed) → muted cyan fallback dot.
	 * </ul>
	 * ItemManager returns an AsyncBufferedImage that self-paints once the
	 * underlying item icon has loaded.
	 */
	private RecordedIcon itemUseIcon(TickActionEvent event)
	{
		int sourceId = event.primaryId();
		int targetId = event.secondaryId();
		if (sourceId <= 0)
		{
			return RecordedIcon.dot(ITEM_USE_FALLBACK);
		}
		BufferedImage source = itemManager.getImage(sourceId);
		if (targetId > 0)
		{
			BufferedImage target = itemManager.getImage(targetId);
			return RecordedIcon.combo(source, target);
		}
		return RecordedIcon.sprite(source);
	}

	/** {@code primaryId} = {@link Prayer#ordinal()}. Defensive bounds check. */
	private BufferedImage prayerSprite(int prayerOrdinal)
	{
		Prayer[] prayers = Prayer.values();
		if (prayerOrdinal < 0 || prayerOrdinal >= prayers.length)
		{
			return null;
		}
		switch (prayers[prayerOrdinal])
		{
			case PROTECT_FROM_MELEE:    return spriteMelee;
			case PROTECT_FROM_MISSILES: return spriteMissiles;
			case PROTECT_FROM_MAGIC:    return spriteMagic;
			default: return null;
		}
	}
}

package com.chromatick;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Immutable snapshot of what the recorder captured at a single tick slot —
 * a list of {@link TickActionEvent}s, one per category that fired this
 * tick. Empty slots return {@link #EMPTY} so callers can use
 * {@link #isEmpty()} instead of null checks.
 *
 * <p>The list is unmodifiable and the events themselves are immutable, so
 * the HUD renderer can read this each frame without coordination.
 */
final class RecordedTick
{
	static final RecordedTick EMPTY = new RecordedTick(Collections.emptyList());

	private final List<TickActionEvent> actions;

	private RecordedTick(List<TickActionEvent> actions)
	{
		this.actions = actions;
	}

	/** Wrap a captured event list. Null/empty inputs collapse to {@link #EMPTY}. */
	static RecordedTick of(List<TickActionEvent> events)
	{
		if (events == null || events.isEmpty())
		{
			return EMPTY;
		}
		return new RecordedTick(Collections.unmodifiableList(new ArrayList<>(events)));
	}

	/** True when no payload was recorded for this tick. */
	boolean isEmpty()
	{
		return actions.isEmpty();
	}

	/** Captured events; never null, possibly empty. Unmodifiable. */
	List<TickActionEvent> actions()
	{
		return actions;
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Bridges RuneLite menu clicks into pending semantic intents. The plugin
 * registers an instance with the event bus in {@code startUp} and resolves
 * those intents from server-side acknowledgement signals in {@code onGameTick};
 * the recorder only stores already-resolved actions.
 *
 * <p>Important distinction: a click is an intent, not a recorded action.
 * Intents stay queued until movement or animation indicates the game has
 * processed one of them on a game tick. This avoids
 * recording "the player clicked during this client tick" when the useful
 * training signal is "the server accepted the action on this game tick".
 *
 * <p>Item-use detection looks at {@link MenuAction}'s family of
 * {@code WIDGET_TARGET_ON_*} values and pulls the source item ID from
 * {@link Client#getSelectedWidget()} - that's the item the player had
 * selected before clicking the target.
 *
 * <p>Threading: RuneLite delivers events on the client thread; the
 * plugin reads on the same thread in {@code onGameTick}. Single-threaded
 * by construction, so the queue is plain (no {@code volatile} needed).
 */
@Singleton
class TickActionCapture
{
	private static final int MAX_PENDING_TICKS = 20;

	private final Client client;
	private final Deque<PendingIntent> pendingIntents = new ArrayDeque<>();
	private int currentClientTick = 0;

	@Inject
	TickActionCapture(Client client)
	{
		this.client = client;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		PendingIntent intent = classify(event);
		if (intent != null)
		{
			pendingIntents.addLast(intent);
		}
	}

	/**
	 * Advance the client-tick marker used for queue aging. Called once from
	 * the plugin's {@code onGameTick} before resolving acknowledgements.
	 */
	void setCurrentClientTick(int currentClientTick)
	{
		this.currentClientTick = currentClientTick;
	}

	/**
	 * Resolve queued intents that have server-side proof on this game tick.
	 * A single movement / animation signal resolves at most one intent each,
	 * while already-active animation can resolve repeated item-on-item uses.
	 */
	List<TickActionEvent> drainAcknowledged(TickAcknowledgement acknowledgement)
	{
		dropStaleIntents();
		if (pendingIntents.isEmpty() || acknowledgement == null || acknowledgement.isEmpty())
		{
			return Collections.emptyList();
		}

		List<TickActionEvent> resolved = new ArrayList<>();
		for (Iterator<PendingIntent> it = pendingIntents.iterator(); it.hasNext(); )
		{
			PendingIntent intent = it.next();
			if (!acknowledgement.consumeFor(intent))
			{
				continue;
			}
			resolved.add(intent.event());
			it.remove();
			if (acknowledgement.isEmpty())
			{
				break;
			}
		}
		return resolved;
	}

	/** Forget any queued intents. Called on shutdown to leave a clean slate. */
	void reset()
	{
		pendingIntents.clear();
		currentClientTick = 0;
	}

	/**
	 * Classify a menu click into one of ITEM_USE / YELLOW_CLICK / RED_CLICK,
	 * or return {@code null} to skip it entirely.
	 *
	 * <p>Matches the OSRS click-cross convention the player actually sees:
	 * the cross only appears on world clicks, never on inventory tab /
	 * spellbook / prayer book / chatbox / RuneLite menu interactions.
	 *
	 * <ul>
	 *   <li><b>null (skipped)</b> - UI/menu clicks (CC_OP, WIDGET_*,
	 *       RuneLite custom menus, CANCEL dismissals). No cross renders
	 *       in-game, so we do not record one either.
	 *   <li>ITEM_USE - any {@code WIDGET_TARGET_ON_*}. Source item ID comes
	 *       from {@link Client#getSelectedWidget()} (the item the player
	 *       picked up the cursor with).
	 *   <li>YELLOW_CLICK - {@link MenuAction#WALK} only. The yellow cross
	 *       in-game appears solely on walk-here clicks (empty terrain or
	 *       a tile with no interactable).
	 *   <li>RED_CLICK - everything else <em>in the world</em>. Talk-to,
	 *       Attack, mine, chop, use-object, examine, cast on NPC, etc.
	 * </ul>
	 */
	private PendingIntent classify(MenuOptionClicked event)
	{
		MenuAction action = event.getMenuAction();
		if (isUiClick(action))
		{
			return null;
		}
		if (isItemUseAction(action))
		{
			int sourceItemId = selectedItemId();
			int targetItemId = targetItemId(event, action);
			return pending(TickActionEvent.of(TickActionCategory.ITEM_USE, sourceItemId, targetItemId),
				action != MenuAction.WIDGET_TARGET_ON_WIDGET,
				action == MenuAction.WIDGET_TARGET_ON_WIDGET);
		}
		if (action == MenuAction.WALK)
		{
			return pending(TickActionEvent.of(TickActionCategory.YELLOW_CLICK, TickActionEvent.NONE), true, false);
		}
		return pending(TickActionEvent.of(TickActionCategory.RED_CLICK, TickActionEvent.NONE), true, false);
	}

	private PendingIntent pending(
		TickActionEvent event,
		boolean movementCanAcknowledge,
		boolean activeAnimationCanAcknowledge)
	{
		return new PendingIntent(event, currentClientTick, System.nanoTime(),
			movementCanAcknowledge, activeAnimationCanAcknowledge);
	}

	private void dropStaleIntents()
	{
		while (!pendingIntents.isEmpty()
			&& currentClientTick - pendingIntents.peekFirst().clientTick() > MAX_PENDING_TICKS)
		{
			pendingIntents.removeFirst();
		}
	}

	/**
	 * True for menu actions that fire on UI/widget interactions - inventory
	 * tabs, spellbook entries, prayer book toggles, chat options, RuneLite
	 * custom menu items, and the dismissal of any context menu. The OSRS
	 * click cross does not render for these, so we do not record them as
	 * red/yellow clicks either.
	 *
	 * <p>Note: {@link MenuAction#WIDGET_TARGET} (the "I selected this item
	 * to use on something" step) is also UI-only. The actual use-on click
	 * comes through as a {@code WIDGET_TARGET_ON_*} action and lands in
	 * ITEM_USE classification later.
	 */
	private static boolean isUiClick(MenuAction action)
	{
		if (action == null)
		{
			return true;
		}
		switch (action)
		{
			case CC_OP:
			case CC_OP_LOW_PRIORITY:
			case WIDGET_TYPE_1:
			case WIDGET_TYPE_4:
			case WIDGET_TYPE_5:
			case WIDGET_TARGET:
			case WIDGET_CLOSE:
			case WIDGET_CONTINUE:
			case WIDGET_FIRST_OPTION:
			case WIDGET_SECOND_OPTION:
			case WIDGET_THIRD_OPTION:
			case WIDGET_FOURTH_OPTION:
			case WIDGET_FIFTH_OPTION:
			case RUNELITE:
			case RUNELITE_WIDGET:
			case RUNELITE_HIGH_PRIORITY:
			case RUNELITE_LOW_PRIORITY:
			case RUNELITE_OVERLAY:
			case RUNELITE_OVERLAY_CONFIG:
			case RUNELITE_PLAYER:
			case RUNELITE_INFOBOX:
			case CANCEL:
				return true;
			default:
				return false;
		}
	}

	private static boolean isItemUseAction(MenuAction action)
	{
		if (action == null)
		{
			return false;
		}
		switch (action)
		{
			case WIDGET_TARGET_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_NPC:
			case WIDGET_TARGET_ON_PLAYER:
			case WIDGET_TARGET_ON_GROUND_ITEM:
			case WIDGET_TARGET_ON_WIDGET:
				return true;
			default:
				return false;
		}
	}

	/**
	 * Item ID of the currently-selected widget (the item the player had
	 * "in hand" before clicking the target). Returns {@link TickActionEvent#NONE}
	 * if no widget is selected or it is not an inventory item.
	 */
	private int selectedItemId()
	{
		if (!client.isWidgetSelected())
		{
			return TickActionEvent.NONE;
		}
		Widget selected = client.getSelectedWidget();
		if (selected == null)
		{
			return TickActionEvent.NONE;
		}
		int itemId = selected.getItemId();
		return itemId > 0 ? itemId : TickActionEvent.NONE;
	}

	/**
	 * Target item ID for an item-use event, or {@link TickActionEvent#NONE}.
	 * Only WIDGET_TARGET_ON_WIDGET clicks have a target inventory item -
	 * use-on-NPC / object / ground-item / player do not, so we return NONE
	 * and the resolver renders the source alone.
	 */
	private static int targetItemId(MenuOptionClicked event, MenuAction action)
	{
		if (action != MenuAction.WIDGET_TARGET_ON_WIDGET)
		{
			return TickActionEvent.NONE;
		}
		int id = event.getItemId();
		return id > 0 ? id : TickActionEvent.NONE;
	}

	private static final class PendingIntent
	{
		private final TickActionEvent event;
		private final int clientTick;
		@SuppressWarnings("unused")
		private final long nanoTime;
		private final boolean movementCanAcknowledge;
		private final boolean activeAnimationCanAcknowledge;

		private PendingIntent(
			TickActionEvent event,
			int clientTick,
			long nanoTime,
			boolean movementCanAcknowledge,
			boolean activeAnimationCanAcknowledge)
		{
			this.event = event;
			this.clientTick = clientTick;
			this.nanoTime = nanoTime;
			this.movementCanAcknowledge = movementCanAcknowledge;
			this.activeAnimationCanAcknowledge = activeAnimationCanAcknowledge;
		}

		private TickActionEvent event()
		{
			return event;
		}

		private int clientTick()
		{
			return clientTick;
		}

		private boolean movementCanAcknowledge()
		{
			return movementCanAcknowledge;
		}

		private boolean activeAnimationCanAcknowledge()
		{
			return activeAnimationCanAcknowledge;
		}
	}

	static final class TickAcknowledgement
	{
		private boolean moved;
		private boolean animationChanged;
		private boolean animating;

		TickAcknowledgement(boolean moved, boolean animationChanged, boolean animating)
		{
			this.moved = moved;
			this.animationChanged = animationChanged;
			this.animating = animating;
		}

		private boolean isEmpty()
		{
			return !moved && !animationChanged && !animating;
		}

		private boolean consumeFor(PendingIntent intent)
		{
			TickActionCategory category = intent.event().category();
			if (category == TickActionCategory.YELLOW_CLICK)
			{
				return consumeMovement(intent);
			}
			if (category == TickActionCategory.RED_CLICK || category == TickActionCategory.ITEM_USE)
			{
				return consumeAnimation()
					|| consumeActiveAnimation(intent)
					|| consumeMovement(intent);
			}
			return false;
		}

		private boolean consumeMovement(PendingIntent intent)
		{
			if (!moved || !intent.movementCanAcknowledge())
			{
				return false;
			}
			moved = false;
			return true;
		}

		private boolean consumeAnimation()
		{
			if (!animationChanged)
			{
				return false;
			}
			animationChanged = false;
			animating = false;
			return true;
		}

		private boolean consumeActiveAnimation(PendingIntent intent)
		{
			if (!animating || !intent.activeAnimationCanAcknowledge())
			{
				return false;
			}
			animating = false;
			return true;
		}

	}
}

package com.chromatick;

import com.chromatick.Enums.*;

/**
 * One categorized player action captured at a single game tick. Immutable
 * value type — the recorder stores these in its per-tick buffer and the
 * icon resolver maps each to its rendered sprite(s).
 *
 * <p>The two ID slots are category-specific and intentionally opaque
 * integers — the resolver is the single seam that knows how to interpret
 * them. Slot conventions:
 *
 * <ul>
 *   <li>{@link TickActionCategory#PROTECTION_PRAYER} —
 *       {@code primaryId} = {@link net.runelite.api.Prayer#ordinal()}.
 *   <li>{@link TickActionCategory#RED_CLICK} —
 *       {@code primaryId} = equipped-weapon item ID (or -1 if unknown),
 *       {@code secondaryId} = target NPC ID (or -1).
 *   <li>{@link TickActionCategory#YELLOW_CLICK} —
 *       {@code primaryId} = -1 (generic cursor glyph),
 *       {@code secondaryId} = target ID (-1 if floor walk-here).
 *   <li>{@link TickActionCategory#ITEM_USE} —
 *       {@code primaryId} = source item ID,
 *       {@code secondaryId} = target item ID (-1 for use-on-object/NPC).
 * </ul>
 */
final class TickActionEvent
{
	static final int NONE = -1;

	private final TickActionCategory category;
	private final int primaryId;
	private final int secondaryId;

	private TickActionEvent(TickActionCategory category, int primaryId, int secondaryId)
	{
		this.category = category;
		this.primaryId = primaryId;
		this.secondaryId = secondaryId;
	}

	/** Two-id event. */
	static TickActionEvent of(TickActionCategory category, int primaryId, int secondaryId)
	{
		return new TickActionEvent(category, primaryId, secondaryId);
	}

	/** Single-id event (secondary = NONE). */
	static TickActionEvent of(TickActionCategory category, int primaryId)
	{
		return new TickActionEvent(category, primaryId, NONE);
	}

	TickActionCategory category()
	{
		return category;
	}

	int primaryId()
	{
		return primaryId;
	}

	int secondaryId()
	{
		return secondaryId;
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;

/**
 * Per-tick recording log for the HUD timeline. State container only — the
 * plugin feeds it the categorized events captured this tick plus a movement
 * signal; the HUD overlay reads back what was recorded at each
 * tick-in-cycle when rendering.
 *
 * <p>Payload is a list of {@link TickActionEvent}s, one per category that
 * fired this tick. Currently only PROTECTION_PRAYER events are emitted by
 * the plugin; the upcoming capture service will add click / item-use /
 * movement events without changing this service.
 *
 * <p>Mode semantics:
 * <ul>
 *   <li>{@link RecordMode#OFF} — never captures.
 *   <li>{@link RecordMode#ARM} — captures the movement tick and a
 *       configurable trailing window (armTicks total). When the window
 *       expires, the recorder transitions itself to OFF (one-shot) but
 *       <em>preserves</em> the captured buffer so the user can review it.
 *   <li>{@link RecordMode#ALWAYS} — captures every tick; subsequent cycles
 *       overdub at the same tick index.
 * </ul>
 *
 * <p>Buffer lifecycle:
 * <ul>
 *   <li>Entering ARM (from any other state) clears the buffer — each ARM
 *       trigger is a fresh capture.
 *   <li>All other transitions preserve the buffer (the ARM auto-exit, the
 *       Always-overdub model, and manual switches to OFF).
 *   <li>{@link #clear()} is the explicit forget-everything path used at
 *       shutdown.
 * </ul>
 *
 * <p>Recordings are keyed by tick-index-in-cycle. Cycle-length changes are
 * not auto-cleared — out-of-range indices are simply ignored by the renderer
 * and will be overwritten as new ticks come around.
 */
@Singleton
class TickRecorderService
{
	private final Map<Integer, List<TickActionEvent>> store = new HashMap<>();

	private RecordMode mode = RecordMode.OFF;
	private int armRemaining = 0;

	RecordMode getMode()
	{
		return mode;
	}

	/**
	 * Set the recorder mode. Entering ARM (from a non-ARM state) clears
	 * the buffer to start a fresh capture session. Other transitions —
	 * including manual moves to OFF and the auto-exit from ARM after a
	 * window expires — preserve the buffer so the recording stays visible.
	 */
	void setMode(RecordMode next)
	{
		if (next == RecordMode.ARM && this.mode != RecordMode.ARM)
		{
			clear();
		}
		this.mode = next;
		this.armRemaining = 0;
	}

	/**
	 * Capture (or skip) the current tick. Called once per {@code GameTick}.
	 *
	 * @param tickIndex position in the cycle, 0-based
	 * @param events    categorized events the plugin observed this tick;
	 *                  may be empty
	 * @param moved     player moved between last tick and this one
	 * @param armTicks  configured ARM window length (1..10); only used
	 *                  when {@code mode == ARM}
	 */
	void onTick(int tickIndex, List<TickActionEvent> events, boolean moved, int armTicks)
	{
		switch (mode)
		{
			case OFF:
				return;
			case ALWAYS:
				capture(tickIndex, events);
				return;
			case ARM:
				if (moved && armRemaining == 0)
				{
					// First movement of this session arms the window. Later
					// movements during the same session don't refresh it —
					// armTicks is the TOTAL capture length (see
					// ChromatickConfig.recordArmTicks: "total ticks to
					// capture"), not a per-step window. Refreshing on every
					// move would let continued walking extend the session
					// past one cycle and silently overwrite the click that
					// started the run when the slot index wrapped back.
					armRemaining = Math.max(1, armTicks);
				}
				if (armRemaining > 0)
				{
					capture(tickIndex, events);
					armRemaining--;
					if (armRemaining == 0)
					{
						// One-shot: window expired, exit ARM. Direct assignment
						// (not via setMode) so the captured buffer is preserved
						// for the user to review.
						mode = RecordMode.OFF;
					}
				}
				return;
		}
	}

	/** True if the buffer holds at least one tick's worth of recorded payload. */
	boolean hasCaptures()
	{
		return !store.isEmpty();
	}

	/**
	 * Recorded payload at this tick-in-cycle, or {@link RecordedTick#EMPTY}
	 * if nothing was captured at that slot.
	 */
	RecordedTick getRecordedAt(int tickIndex)
	{
		return RecordedTick.of(store.get(tickIndex));
	}

	/** Forget everything. Called on entering OFF, on shutdown, and on demand. */
	void clear()
	{
		store.clear();
		armRemaining = 0;
	}

	private void capture(int tickIndex, List<TickActionEvent> events)
	{
		// Defensive copy so the caller can reuse its list. Events themselves
		// are immutable, so a shallow copy of the references is sufficient.
		store.put(tickIndex, events == null || events.isEmpty()
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(events)));
	}
}

package com.chromatick;

import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Tests for the legacy-value config migrator. Uses a mocked ConfigManager so
 * we can assert exact read/write calls without standing up a RuneLite runtime.
 *
 * <p>The migrator's job is narrow: rewrite raw lowercase strings stored under
 * the four enum-typed keys into their canonical {@code Enum#name()} form.
 * Already-canonical and unknown values must be left alone.
 */
public class ChromatickConfigMigratorTest
{
	private static final String GROUP = "chromatick";

	private ConfigManager configManager;
	private ChromatickConfigMigrator migrator;

	@Before
	public void setUp()
	{
		configManager = mock(ConfigManager.class);
		when(configManager.getConfiguration(eq(GROUP), anyString())).thenReturn(null);
		migrator = new ChromatickConfigMigrator(configManager);
	}

	@Test
	public void doesNothingWhenAllValuesAreNull()
	{
		migrator.migrate();

		verify(configManager, never()).setConfiguration(eq(GROUP), anyString(), any(String.class));
	}

	@Test
	public void leavesAlreadyCanonicalValuesAlone()
	{
		when(configManager.getConfiguration(GROUP, "displayMode")).thenReturn("HUD");
		when(configManager.getConfiguration(GROUP, "hudGlyph")).thenReturn("NUMBERS");
		when(configManager.getConfiguration(GROUP, "hudAnchorTarget")).thenReturn("FEET");
		when(configManager.getConfiguration(GROUP, "paletteMode")).thenReturn("WHEEL");

		migrator.migrate();

		verify(configManager, never()).setConfiguration(eq(GROUP), anyString(), any(String.class));
	}

	@Test
	public void rewritesLegacyLowercaseDisplayMode()
	{
		when(configManager.getConfiguration(GROUP, "displayMode")).thenReturn("hud");

		migrator.migrate();

		verify(configManager).setConfiguration(GROUP, "displayMode", "HUD");
	}

	@Test
	public void rewritesLegacyLowercaseHudGlyph()
	{
		when(configManager.getConfiguration(GROUP, "hudGlyph")).thenReturn("numbers");

		migrator.migrate();

		verify(configManager).setConfiguration(GROUP, "hudGlyph", "NUMBERS");
	}

	@Test
	public void rewritesLegacyLowercaseHudAnchorTarget()
	{
		when(configManager.getConfiguration(GROUP, "hudAnchorTarget")).thenReturn("head");

		migrator.migrate();

		verify(configManager).setConfiguration(GROUP, "hudAnchorTarget", "HEAD");
	}

	@Test
	public void rewritesLegacyLowercasePaletteMode()
	{
		when(configManager.getConfiguration(GROUP, "paletteMode")).thenReturn("wheel");

		migrator.migrate();

		verify(configManager).setConfiguration(GROUP, "paletteMode", "WHEEL");
	}

	@Test
	public void rewritesMixedCaseAndOtherCasings()
	{
		when(configManager.getConfiguration(GROUP, "displayMode")).thenReturn("Hud");
		when(configManager.getConfiguration(GROUP, "paletteMode")).thenReturn("Grid");

		migrator.migrate();

		verify(configManager).setConfiguration(GROUP, "displayMode", "HUD");
		verify(configManager).setConfiguration(GROUP, "paletteMode", "GRID");
	}

	@Test
	public void leavesUnknownLegacyValuesAlone()
	{
		// Garbage value — shouldn't crash, shouldn't write anything. RuneLite
		// will then fall back to the @ConfigItem default.
		when(configManager.getConfiguration(GROUP, "displayMode")).thenReturn("garbage");

		migrator.migrate();

		verify(configManager, never()).setConfiguration(eq(GROUP), anyString(), any(String.class));
	}

	@Test
	public void treatsEmptyStringAsAbsent()
	{
		when(configManager.getConfiguration(GROUP, "displayMode")).thenReturn("");

		migrator.migrate();

		verify(configManager, never()).setConfiguration(eq(GROUP), anyString(), any(String.class));
	}

	@Test
	public void migrationIsIdempotent()
	{
		// Run, then re-run with the now-canonical value — the second pass must
		// not re-write anything.
		when(configManager.getConfiguration(GROUP, "displayMode"))
			.thenReturn("hud")     // first call: legacy lowercase
			.thenReturn("HUD");    // second call: already migrated

		migrator.migrate();
		migrator.migrate();

		// Only the first call should have written.
		verify(configManager).setConfiguration(GROUP, "displayMode", "HUD");
	}
}

package com.chromatick;

import java.awt.Point;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Edge-case coverage for {@link ChromatickHudOverlay#wasDragged} — the pure
 * predicate that decides whether the framework's preferred-location update
 * was a user alt-drag (versus a window-resize nudge, a first-frame seed, or
 * a frame where the overlay hasn't been positioned yet).
 */
public class ChromatickHudOverlayDragDetectionTest
{
	@Test
	public void returnsFalseWhenCanvasJustResized()
	{
		// Window resize moves the overlay back inside bounds; that nudge
		// must not be misread as an alt-drag.
		Point lastSet = new Point(100, 100);
		Point current = new Point(95,  100);

		assertFalse(ChromatickHudOverlay.wasDragged(true, lastSet, current));
	}

	@Test
	public void returnsFalseWhenLastSetLocationIsNull()
	{
		// Haven't anchored yet (first frame after re-add) — nothing to compare.
		assertFalse(ChromatickHudOverlay.wasDragged(false, null, new Point(50, 50)));
	}

	@Test
	public void returnsFalseWhenPreferredLocationIsNull()
	{
		// Framework hasn't reported a preferred location yet.
		assertFalse(ChromatickHudOverlay.wasDragged(false, new Point(50, 50), null));
	}

	@Test
	public void returnsFalseWhenLocationsMatch()
	{
		Point p = new Point(100, 100);

		assertFalse(ChromatickHudOverlay.wasDragged(false, p, new Point(100, 100)));
		// Same Point reference is equally fine.
		assertFalse(ChromatickHudOverlay.wasDragged(false, p, p));
	}

	@Test
	public void returnsTrueWhenPreferredLocationHasMovedHorizontally()
	{
		assertTrue(ChromatickHudOverlay.wasDragged(false,
			new Point(100, 100), new Point(150, 100)));
	}

	@Test
	public void returnsTrueWhenPreferredLocationHasMovedVertically()
	{
		assertTrue(ChromatickHudOverlay.wasDragged(false,
			new Point(100, 100), new Point(100, 80)));
	}

	@Test
	public void returnsTrueOnEvenASinglePixelShift()
	{
		// Conservative: any movement is a drag. Avoids missing tiny but
		// intentional repositions.
		assertTrue(ChromatickHudOverlay.wasDragged(false,
			new Point(100, 100), new Point(101, 100)));
	}

	@Test
	public void resizeFlagOverridesAllOtherSignals()
	{
		// Even with a clear position delta, the resize flag suppresses
		// drag detection for that frame.
		assertFalse(ChromatickHudOverlay.wasDragged(true,
			new Point(0, 0), new Point(500, 500)));
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.awt.Color;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Tests for {@link ChromatickPanelSnapshot#from} — verify each config getter
 * maps to the matching snapshot field, and that the effective-cycle and
 * record-categories arguments are passed through verbatim (so hotkey
 * overrides surface in the panel without it having to call back into the
 * plugin).
 *
 * <p>Uses a Mockito-mocked {@link ChromatickConfig}; RuneLite's
 * {@link ConfigManager} isn't needed because the snapshot only reads via the
 * typed config interface.
 */
public class ChromatickPanelSnapshotTest
{
	private static final Set<TickActionCategory> PRAYER_ONLY =
		Collections.singleton(TickActionCategory.PROTECTION_PRAYER);

	/**
	 * Anonymous ChromatickConfig with every method left at its declared
	 * default. Hand-rolled instead of Mockito.CALLS_REAL_METHODS because
	 * the latter relies on MethodHandles.Lookup.findSpecial under the
	 * hood, which Mockito 3.12.4 can't drive against JDK 17+ without
	 * extra module opens. Plain instantiation works because Config is a
	 * marker interface and every ChromatickConfig method has a default
	 * implementation.
	 */
	private static ChromatickConfig defaultsConfig()
	{
		return new ChromatickConfig() {};
	}

	@Test
	public void defaultsRoundTripThroughTheSnapshot()
	{
		// A config returning all its declared defaults — the snapshot should
		// mirror them exactly.
		ChromatickConfig cfg = defaultsConfig();

		ChromatickPanelSnapshot s = ChromatickPanelSnapshot.from(cfg, 4, PRAYER_ONLY);

		assertFalse(s.staticMode);
		assertEquals(PaletteMode.GRID, s.paletteMode);
		assertTrue(s.sequentialFill);
		assertEquals(2.0, s.tileBorderWidth, 0.0001);
		assertTrue(s.enableFillColor);
		assertEquals(50, s.fillOpacity);
		assertFalse(s.drawBelowPlayer);
		assertEquals(DisplayMode.TILE, s.displayMode);
		assertEquals(HudGlyph.DOTS, s.hudGlyph);
		assertEquals(200, s.hudScale);
		assertEquals(100, s.hudActiveOpacity);
		assertEquals(40, s.hudInactiveOpacity);
		assertFalse(s.hudBold);
		assertEquals(0, s.hudPop);
		assertEquals(0, s.hudSpacing);
		assertFalse(s.hudVertical);
		assertEquals(HudAnchorTarget.FEET, s.hudAnchorTarget);
		assertEquals(30, s.hudVerticalOffset);
		assertEquals(0, s.hudHorizontalOffset);
		assertFalse(s.hudCycleInPlace);
		assertEquals(RecordMode.OFF, s.recordMode);
		assertEquals(IconPosition.ABOVE, s.recordIconPosition);
		assertEquals(1, s.recordArmTicks);
		assertEquals(PRAYER_ONLY, s.recordCategories);
		assertEquals(4, s.effectiveCycleLength);
	}

	@Test
	public void overriddenConfigValuesAreMirrored()
	{
		// Spot-check every field with a non-default value to guard against
		// builder-arg ordering mishaps.
		ChromatickConfig cfg = mock(ChromatickConfig.class);
		Color sc = new Color(10, 20, 30, 200);
		Color sf = new Color(40, 50, 60, 100);
		when(cfg.staticMode()).thenReturn(true);
		when(cfg.paletteMode()).thenReturn(PaletteMode.WHEEL);
		when(cfg.sequentialFill()).thenReturn(false);
		when(cfg.staticColor()).thenReturn(sc);
		when(cfg.staticFillColor()).thenReturn(sf);
		when(cfg.tileBorderWidth()).thenReturn(3.5);
		when(cfg.enableFillColor()).thenReturn(false);
		when(cfg.fillOpacity()).thenReturn(77);
		when(cfg.drawBelowPlayer()).thenReturn(true);
		when(cfg.displayMode()).thenReturn(DisplayMode.BOTH);
		when(cfg.hudGlyph()).thenReturn(HudGlyph.NUMBERS);
		when(cfg.hudScale()).thenReturn(310);
		when(cfg.hudActiveOpacity()).thenReturn(85);
		when(cfg.hudInactiveOpacity()).thenReturn(15);
		when(cfg.hudBold()).thenReturn(true);
		when(cfg.hudPop()).thenReturn(120);
		when(cfg.hudSpacing()).thenReturn(-5);
		when(cfg.hudVertical()).thenReturn(true);
		when(cfg.hudAnchorTarget()).thenReturn(HudAnchorTarget.HEAD);
		when(cfg.hudVerticalOffset()).thenReturn(-12);
		when(cfg.hudHorizontalOffset()).thenReturn(42);
		when(cfg.hudCycleInPlace()).thenReturn(true);
		when(cfg.recordMode()).thenReturn(RecordMode.ALWAYS);
		when(cfg.recordIconPosition()).thenReturn(IconPosition.BELOW);
		when(cfg.recordArmTicks()).thenReturn(7);
		Set<TickActionCategory> threeCats = EnumSet.of(
			TickActionCategory.PROTECTION_PRAYER,
			TickActionCategory.RED_CLICK,
			TickActionCategory.YELLOW_CLICK);

		ChromatickPanelSnapshot s = ChromatickPanelSnapshot.from(cfg, 9, threeCats);

		assertTrue(s.staticMode);
		assertEquals(PaletteMode.WHEEL, s.paletteMode);
		assertFalse(s.sequentialFill);
		assertSame(sc, s.staticColor);
		assertSame(sf, s.staticFillColor);
		assertEquals(3.5, s.tileBorderWidth, 0.0001);
		assertFalse(s.enableFillColor);
		assertEquals(77, s.fillOpacity);
		assertTrue(s.drawBelowPlayer);
		assertEquals(DisplayMode.BOTH, s.displayMode);
		assertEquals(HudGlyph.NUMBERS, s.hudGlyph);
		assertEquals(310, s.hudScale);
		assertEquals(85, s.hudActiveOpacity);
		assertEquals(15, s.hudInactiveOpacity);
		assertTrue(s.hudBold);
		assertEquals(120, s.hudPop);
		assertEquals(-5, s.hudSpacing);
		assertTrue(s.hudVertical);
		assertEquals(HudAnchorTarget.HEAD, s.hudAnchorTarget);
		assertEquals(-12, s.hudVerticalOffset);
		assertEquals(42, s.hudHorizontalOffset);
		assertTrue(s.hudCycleInPlace);
		assertEquals(RecordMode.ALWAYS, s.recordMode);
		assertEquals(IconPosition.BELOW, s.recordIconPosition);
		assertEquals(7, s.recordArmTicks);
		assertEquals(threeCats, s.recordCategories);
		assertEquals(9, s.effectiveCycleLength);
	}

	@Test
	public void effectiveCycleLengthIsPassedThroughUnchanged()
	{
		// effectiveCycleLength reflects hotkey override; the snapshot factory
		// must not second-guess it (no clamping, no reading cycleLength from
		// config). Pass-through is the contract.
		ChromatickConfig cfg = defaultsConfig();

		assertEquals(2,  ChromatickPanelSnapshot.from(cfg, 2, PRAYER_ONLY).effectiveCycleLength);
		assertEquals(10, ChromatickPanelSnapshot.from(cfg, 10, PRAYER_ONLY).effectiveCycleLength);
		// Even nonsensical values are passed through — clamping is the
		// caller's responsibility.
		assertEquals(99, ChromatickPanelSnapshot.from(cfg, 99, PRAYER_ONLY).effectiveCycleLength);
	}

	@Test
	public void recordCategoriesArePassedThroughUnchanged()
	{
		// The plugin parses recordCategories from a CSV string before
		// calling from(...); the snapshot factory just stores the set.
		ChromatickConfig cfg = defaultsConfig();

		Set<TickActionCategory> all = EnumSet.allOf(TickActionCategory.class);
		assertEquals(all, ChromatickPanelSnapshot.from(cfg, 4, all).recordCategories);

		Set<TickActionCategory> none = EnumSet.noneOf(TickActionCategory.class);
		assertEquals(none, ChromatickPanelSnapshot.from(cfg, 4, none).recordCategories);
	}
}

