package com.chromatick;

import com.google.gson.Gson;
import java.awt.Color;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import net.runelite.client.config.ConfigManager;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Tests for the persistence-backed instance methods on {@link PaletteService}.
 * Uses a real {@link Gson} (so JSON shape is exercised end-to-end) and a
 * mocked {@link ConfigManager} (so we can assert on read/write calls without
 * a real RuneLite runtime).
 */
public class PaletteServiceTest
{
	private static final String GROUP = "chromatick";

	private ConfigManager configManager;
	private PaletteService palettes;

	@Before
	public void setUp()
	{
		configManager = mock(ConfigManager.class);
		palettes = new PaletteService(configManager, new Gson());
		// Default: every config read returns null (i.e. no custom palette set).
		// Individual tests can override per-key with their own when(...).
		when(configManager.getConfiguration(eq(GROUP), any())).thenReturn(null);
	}

	// ─── getCustomPaletteForCycle ────────────────────────────────────────

	@Test
	public void returnsDefaultPaletteCloneWhenConfigIsNull()
	{
		Color[] result = palettes.getCustomPaletteForCycle(4);

		assertArrayEquals(PaletteService.PALETTES[4], result);
		// Mutating the returned array must not touch the static defaults.
		result[0] = Color.BLACK;
		assertEquals(new Color(255, 64, 64), PaletteService.PALETTES[4][0]);
	}

	@Test
	public void returnsDefaultPaletteCloneWhenConfigIsEmptyString()
	{
		when(configManager.getConfiguration(GROUP, "customPalette4")).thenReturn("");

		Color[] result = palettes.getCustomPaletteForCycle(4);

		assertArrayEquals(PaletteService.PALETTES[4], result);
	}

	@Test
	public void returnsCustomPaletteWhenConfigIsValidJson()
	{
		// 4 RGBs as ARGB ints — black, white, red, green (alpha 0xFF).
		String json = "[-16777216,-1,-65536,-16711936]";
		when(configManager.getConfiguration(GROUP, "customPalette4")).thenReturn(json);

		Color[] result = palettes.getCustomPaletteForCycle(4);

		assertEquals(4, result.length);
		assertEquals(Color.BLACK.getRGB(), result[0].getRGB());
		assertEquals(Color.WHITE.getRGB(), result[1].getRGB());
		assertEquals(Color.RED.getRGB(),   result[2].getRGB());
		assertEquals(Color.GREEN.getRGB(), result[3].getRGB());
	}

	@Test
	public void fallsBackToDefaultsForMissingEntriesInShortJson()
	{
		// Only 2 of 4 slots present — the rest must inherit defaults.
		String json = "[-16777216,-1]";
		when(configManager.getConfiguration(GROUP, "customPalette4")).thenReturn(json);

		Color[] result = palettes.getCustomPaletteForCycle(4);

		assertEquals(4, result.length);
		assertEquals(Color.BLACK.getRGB(), result[0].getRGB());
		assertEquals(Color.WHITE.getRGB(), result[1].getRGB());
		assertEquals(PaletteService.PALETTES[4][2], result[2]);
		assertEquals(PaletteService.PALETTES[4][3], result[3]);
	}

	@Test
	public void fallsBackToDefaultsForNullEntriesInJson()
	{
		String json = "[null,-1,null,-65536]";
		when(configManager.getConfiguration(GROUP, "customPalette4")).thenReturn(json);

		Color[] result = palettes.getCustomPaletteForCycle(4);

		assertEquals(PaletteService.PALETTES[4][0], result[0]);
		assertEquals(Color.WHITE.getRGB(), result[1].getRGB());
		assertEquals(PaletteService.PALETTES[4][2], result[2]);
		assertEquals(Color.RED.getRGB(), result[3].getRGB());
	}

	@Test
	public void fallsBackToDefaultsForUnparseableJson()
	{
		when(configManager.getConfiguration(GROUP, "customPalette4")).thenReturn("not-json");

		Color[] result = palettes.getCustomPaletteForCycle(4);

		assertArrayEquals(PaletteService.PALETTES[4], result);
	}

	@Test
	public void clampsCycleLengthOnRead()
	{
		// Out-of-range cycle should resolve against PALETTES[10], not crash.
		Color[] result = palettes.getCustomPaletteForCycle(99);

		assertEquals(10, result.length);
		assertArrayEquals(PaletteService.PALETTES[10], result);
		// And it should have read the config under the clamped key, not "customPalette99".
		verify(configManager).getConfiguration(GROUP, "customPalette10");
	}

	// ─── setCustomPaletteColor ───────────────────────────────────────────

	@Test
	public void setCustomPaletteColorPersistsRgbList()
	{
		palettes.setCustomPaletteColor(4, 1, Color.MAGENTA);

		ArgumentCaptor<String> json = ArgumentCaptor.forClass(String.class);
		verify(configManager).setConfiguration(eq(GROUP), eq("customPalette4"), json.capture());

		// Decode the written JSON back through Gson and verify it round-trips
		// the magenta override at index 1, with defaults preserved elsewhere.
		Integer[] rgbs = new Gson().fromJson(json.getValue(), Integer[].class);
		assertEquals(4, rgbs.length);
		assertEquals(PaletteService.PALETTES[4][0].getRGB(), (int) rgbs[0]);
		assertEquals(Color.MAGENTA.getRGB(),                  (int) rgbs[1]);
		assertEquals(PaletteService.PALETTES[4][2].getRGB(), (int) rgbs[2]);
		assertEquals(PaletteService.PALETTES[4][3].getRGB(), (int) rgbs[3]);
	}

	@Test
	public void setCustomPaletteColorIsNoOpForOutOfBoundsIndex()
	{
		palettes.setCustomPaletteColor(4, -1, Color.MAGENTA);
		palettes.setCustomPaletteColor(4, 4,  Color.MAGENTA);
		palettes.setCustomPaletteColor(4, 99, Color.MAGENTA);

		verify(configManager, never()).setConfiguration(eq(GROUP), any(), any(String.class));
	}

	@Test
	public void setCustomPaletteColorClampsCycleLength()
	{
		palettes.setCustomPaletteColor(99, 0, Color.MAGENTA);

		// Should write under the clamped key (cycle 10), not "customPalette99".
		verify(configManager).setConfiguration(eq(GROUP), eq("customPalette10"), any(String.class));
	}

	// ─── resetCustomPaletteForCycle ──────────────────────────────────────

	@Test
	public void resetCustomPaletteUnsetsConfigKey()
	{
		palettes.resetCustomPaletteForCycle(6);

		verify(configManager, times(1)).unsetConfiguration(GROUP, "customPalette6");
	}

	@Test
	public void resetCustomPaletteClampsCycleLength()
	{
		palettes.resetCustomPaletteForCycle(0);

		verify(configManager).unsetConfiguration(GROUP, "customPalette2");
	}
}

package com.chromatick;

import java.awt.Color;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Characterization tests for the static {@code PALETTES} table. These pin
 * down the perceptual contract (one palette per cycle 2..10, no nulls, fully
 * opaque, no duplicate colors within a palette) so a future refactor that
 * regenerates the table doesn't silently break it.
 */
public class PalettesTest
{
	private static final int MIN_CYCLE = 2;
	private static final int MAX_CYCLE = 10;

	@Test
	public void paletteArrayCoversCyclesTwoThroughTen()
	{
		assertEquals("PALETTES is indexed by cycle length; needs slots 0..10",
			MAX_CYCLE + 1, PaletteService.PALETTES.length);
	}

	@Test
	public void cycleZeroAndOneAreUnused()
	{
		assertNull("cycle 0 slot is intentionally unused", PaletteService.PALETTES[0]);
		assertNull("cycle 1 slot is intentionally unused", PaletteService.PALETTES[1]);
	}

	@Test
	public void everyValidCycleHasMatchingPaletteLength()
	{
		for (int n = MIN_CYCLE; n <= MAX_CYCLE; n++)
		{
			Color[] palette = PaletteService.PALETTES[n];
			assertNotNull("palette for cycle " + n + " must exist", palette);
			assertEquals("palette[" + n + "] must have " + n + " colors",
				n, palette.length);
		}
	}

	@Test
	public void noPaletteContainsNullEntries()
	{
		for (int n = MIN_CYCLE; n <= MAX_CYCLE; n++)
		{
			Color[] palette = PaletteService.PALETTES[n];
			for (int i = 0; i < palette.length; i++)
			{
				assertNotNull("palette[" + n + "][" + i + "] is null", palette[i]);
			}
		}
	}

	@Test
	public void allPaletteColorsAreFullyOpaque()
	{
		// Tile/HUD overlays layer their own alpha on top of palette RGB. If a
		// palette entry ever lands with a non-255 alpha (e.g. via a Color(int)
		// constructor that picked up the alpha byte), the rendered alpha would
		// silently double up.
		for (int n = MIN_CYCLE; n <= MAX_CYCLE; n++)
		{
			Color[] palette = PaletteService.PALETTES[n];
			for (int i = 0; i < palette.length; i++)
			{
				assertEquals("palette[" + n + "][" + i + "] must be fully opaque",
					255, palette[i].getAlpha());
			}
		}
	}

	@Test
	public void paletteColorsAreUniqueWithinEachCycle()
	{
		// Preattentive distinctness is the whole point — duplicates inside a
		// single cycle would defeat the plugin's UX goal.
		for (int n = MIN_CYCLE; n <= MAX_CYCLE; n++)
		{
			Color[] palette = PaletteService.PALETTES[n];
			Set<Integer> seen = new HashSet<>();
			for (int i = 0; i < palette.length; i++)
			{
				int rgb = palette[i].getRGB();
				assertTrue("palette[" + n + "] contains duplicate color at index " + i,
					seen.add(rgb));
			}
		}
	}

	@Test
	public void firstColorIsRedAcrossAllCycles()
	{
		// The current palettes all start at red (255, 64, 64) — this anchors
		// the cycle's "tick 0" to a consistent landmark so users developing
		// muscle memory at one cycle length carry it over to others.
		Color expected = new Color(255, 64, 64);
		for (int n = MIN_CYCLE; n <= MAX_CYCLE; n++)
		{
			assertEquals("palette[" + n + "][0] should anchor at red",
				expected, PaletteService.PALETTES[n][0]);
		}
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Tests for the {@link RecordedTick} value type. Narrow surface — it just
 * wraps "what the recorder captured at one tick slot" — but the contract
 * (EMPTY singleton for absent payload, unmodifiable view, defensive copy
 * of caller-mutated input) is what downstream consumers rely on.
 */
public class RecordedTickTest
{
	private static TickActionEvent prayer()
	{
		return TickActionEvent.of(TickActionCategory.PROTECTION_PRAYER, 0);
	}

	@Test
	public void emptyIsTheSentinelForAbsentPayload()
	{
		assertTrue(RecordedTick.EMPTY.isEmpty());
		assertTrue(RecordedTick.EMPTY.actions().isEmpty());
	}

	@Test
	public void ofWithNullCollapsesToEmpty()
	{
		assertSame(RecordedTick.EMPTY, RecordedTick.of(null));
	}

	@Test
	public void ofWithEmptyCollapsesToEmpty()
	{
		assertSame(RecordedTick.EMPTY, RecordedTick.of(Collections.emptyList()));
		assertSame(RecordedTick.EMPTY, RecordedTick.of(new ArrayList<>()));
	}

	@Test
	public void ofExposesTheCapturedEvents()
	{
		List<TickActionEvent> captured = Arrays.asList(prayer(), prayer());
		RecordedTick tick = RecordedTick.of(captured);

		assertFalse(tick.isEmpty());
		assertEquals(2, tick.actions().size());
	}

	@Test
	public void actionsViewIsUnmodifiable()
	{
		// HUD render reads the view each frame; mutations from there must not
		// be possible (would corrupt the recorder's internal buffer).
		RecordedTick tick = RecordedTick.of(Collections.singletonList(prayer()));
		try
		{
			tick.actions().add(prayer());
			assertTrue("expected UnsupportedOperationException", false);
		}
		catch (UnsupportedOperationException expected)
		{
			// good
		}
	}

	@Test
	public void ofDefensiveCopiesTheCallerList()
	{
		// Caller mutates the list it passed in — the recorded snapshot
		// must not reflect that change.
		List<TickActionEvent> mutable = new ArrayList<>();
		mutable.add(prayer());
		RecordedTick tick = RecordedTick.of(mutable);

		mutable.add(prayer());
		mutable.add(prayer());

		assertEquals(1, tick.actions().size());
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Tests for {@link TickActionCapture}. Menu clicks are pending intents; they
 * become {@link TickActionEvent}s only when a server-side acknowledgement signal
 * resolves them on a game tick.
 */
public class TickActionCaptureTest
{
	private Client client;
	private TickActionCapture capture;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		when(client.isWidgetSelected()).thenReturn(false);
		capture = new TickActionCapture(client);
	}

	private static MenuOptionClicked clickEvent(MenuAction action)
	{
		MenuOptionClicked e = mock(MenuOptionClicked.class);
		when(e.getMenuAction()).thenReturn(action);
		return e;
	}

	private static TickActionCapture.TickAcknowledgement ack(
		boolean moved,
		boolean animationChanged)
	{
		return ack(moved, animationChanged, animationChanged);
	}

	private static TickActionCapture.TickAcknowledgement ack(
		boolean moved,
		boolean animationChanged,
		boolean animating)
	{
		return new TickActionCapture.TickAcknowledgement(moved, animationChanged, animating);
	}

	private static TickActionCapture.TickAcknowledgement none()
	{
		return ack(false, false);
	}

	private void setSelectedItem(int itemId)
	{
		Widget selected = mock(Widget.class);
		when(selected.getItemId()).thenReturn(itemId);
		when(client.isWidgetSelected()).thenReturn(true);
		when(client.getSelectedWidget()).thenReturn(selected);
	}

	private MenuOptionClicked itemUseClick(int targetItemId)
	{
		MenuOptionClicked e = mock(MenuOptionClicked.class);
		when(e.getMenuAction()).thenReturn(MenuAction.WIDGET_TARGET_ON_WIDGET);
		when(e.getItemId()).thenReturn(targetItemId);
		return e;
	}

	@Test
	public void walkIntentWaitsForMovementAcknowledgement()
	{
		capture.onMenuOptionClicked(clickEvent(MenuAction.WALK));

		assertTrue(capture.drainAcknowledged(none()).isEmpty());

		List<TickActionEvent> resolved = capture.drainAcknowledged(ack(true, false));
		assertEquals(1, resolved.size());
		assertEquals(TickActionCategory.YELLOW_CLICK, resolved.get(0).category());
	}

	@Test
	public void redIntentWaitsForAnimationOrMovementAcknowledgement()
	{
		capture.onMenuOptionClicked(clickEvent(MenuAction.NPC_FIRST_OPTION));

		assertTrue(capture.drainAcknowledged(none()).isEmpty());

		List<TickActionEvent> resolved = capture.drainAcknowledged(ack(false, true));
		assertEquals(1, resolved.size());
		assertEquals(TickActionCategory.RED_CLICK, resolved.get(0).category());
	}

	@Test
	public void itemUseOnWidgetCanResolveFromAnimationButNotMovement()
	{
		setSelectedItem(946);
		capture.onMenuOptionClicked(itemUseClick(1511));

		assertTrue(capture.drainAcknowledged(ack(true, false)).isEmpty());

		List<TickActionEvent> resolved = capture.drainAcknowledged(ack(false, true));
		assertEquals(1, resolved.size());
		assertEquals(TickActionCategory.ITEM_USE, resolved.get(0).category());
		assertEquals(946, resolved.get(0).primaryId());
		assertEquals(1511, resolved.get(0).secondaryId());
	}

	@Test
	public void itemUseOnWidgetCanResolveWhileAlreadyAnimating()
	{
		setSelectedItem(946);
		capture.onMenuOptionClicked(itemUseClick(1511));

		List<TickActionEvent> resolved = capture.drainAcknowledged(ack(false, false, true));
		assertEquals(1, resolved.size());
		assertEquals(TickActionCategory.ITEM_USE, resolved.get(0).category());
		assertEquals(946, resolved.get(0).primaryId());
		assertEquals(1511, resolved.get(0).secondaryId());
	}

	@Test
	public void redIntentDoesNotResolveFromAlreadyAnimatingAlone()
	{
		capture.onMenuOptionClicked(clickEvent(MenuAction.NPC_FIRST_OPTION));

		assertTrue(capture.drainAcknowledged(ack(false, false, true)).isEmpty());
	}

	@Test
	public void itemUseOnWorldTargetCanResolveFromMovement()
	{
		MenuOptionClicked e = mock(MenuOptionClicked.class);
		when(e.getMenuAction()).thenReturn(MenuAction.WIDGET_TARGET_ON_GAME_OBJECT);
		setSelectedItem(946);
		capture.onMenuOptionClicked(e);

		List<TickActionEvent> resolved = capture.drainAcknowledged(ack(true, false));
		assertEquals(1, resolved.size());
		assertEquals(TickActionCategory.ITEM_USE, resolved.get(0).category());
		assertEquals(946, resolved.get(0).primaryId());
		assertEquals(TickActionEvent.NONE, resolved.get(0).secondaryId());
	}

	@Test
	public void uiClickIsFilteredOut()
	{
		capture.onMenuOptionClicked(clickEvent(MenuAction.CC_OP));

		assertTrue(capture.drainAcknowledged(ack(true, true)).isEmpty());
	}

	@Test
	public void cancelIsFilteredOut()
	{
		capture.onMenuOptionClicked(clickEvent(MenuAction.CANCEL));

		assertTrue(capture.drainAcknowledged(ack(true, true)).isEmpty());
	}

	@Test
	public void pendingIntentsResolveInFifoOrderAcrossTicks()
	{
		capture.onMenuOptionClicked(clickEvent(MenuAction.WALK));
		capture.onMenuOptionClicked(clickEvent(MenuAction.NPC_FIRST_OPTION));

		List<TickActionEvent> first = capture.drainAcknowledged(ack(true, false));
		assertEquals(1, first.size());
		assertEquals(TickActionCategory.YELLOW_CLICK, first.get(0).category());

		List<TickActionEvent> second = capture.drainAcknowledged(ack(false, true));
		assertEquals(1, second.size());
		assertEquals(TickActionCategory.RED_CLICK, second.get(0).category());
	}

	@Test
	public void multipleAcknowledgementSignalsCanResolveMultipleIntentsOnSameTick()
	{
		capture.onMenuOptionClicked(clickEvent(MenuAction.WALK));
		capture.onMenuOptionClicked(clickEvent(MenuAction.NPC_FIRST_OPTION));

		List<TickActionEvent> resolved = capture.drainAcknowledged(ack(true, true));
		assertEquals(2, resolved.size());
		assertEquals(TickActionCategory.YELLOW_CLICK, resolved.get(0).category());
		assertEquals(TickActionCategory.RED_CLICK, resolved.get(1).category());
	}

	@Test
	public void staleIntentsAreDroppedWithoutRecording()
	{
		capture.onMenuOptionClicked(clickEvent(MenuAction.WALK));

		capture.setCurrentClientTick(21);

		assertTrue(capture.drainAcknowledged(ack(true, false)).isEmpty());
	}

	@Test
	public void resetForgetsAnyQueuedIntent()
	{
		capture.onMenuOptionClicked(clickEvent(MenuAction.NPC_FIRST_OPTION));
		capture.reset();

		assertTrue(capture.drainAcknowledged(ack(false, true)).isEmpty());
	}
}

package com.chromatick;

import com.chromatick.Enums.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Prayer;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests for the per-tick recorder state machine. All inputs are plain ints,
 * Prayer constants and TickActionEvent lists — no RuneLite injection
 * required.
 *
 * <p>Constants like {@link #MELEE} remain {@code Set<Prayer>} for readable
 * assertions; the {@link #events(Set)} helper wraps them into the
 * {@code List<TickActionEvent>} the recorder accepts, and
 * {@link #prayersAt(int)} unwraps the recorded payload back into a Prayer
 * set for the same assertions.
 */
public class TickRecorderServiceTest
{
	private static final Set<Prayer> MELEE   = Collections.singleton(Prayer.PROTECT_FROM_MELEE);
	private static final Set<Prayer> MAGIC   = Collections.singleton(Prayer.PROTECT_FROM_MAGIC);
	private static final Set<Prayer> MISSILE = Collections.singleton(Prayer.PROTECT_FROM_MISSILES);
	private static final Set<Prayer> NONE    = Collections.emptySet();

	private TickRecorderService recorder;

	@Before
	public void setUp()
	{
		recorder = new TickRecorderService();
	}

	/** Build the event list the recorder accepts from a prayer set. */
	private static List<TickActionEvent> events(Set<Prayer> prayers)
	{
		if (prayers.isEmpty())
		{
			return Collections.emptyList();
		}
		List<TickActionEvent> out = new ArrayList<>(prayers.size());
		for (Prayer p : prayers)
		{
			out.add(TickActionEvent.of(TickActionCategory.PROTECTION_PRAYER, p.ordinal()));
		}
		return out;
	}

	/** Extract the prayer set back out of the recorded tick. */
	private Set<Prayer> prayersAt(int tickIndex)
	{
		Set<Prayer> out = EnumSet.noneOf(Prayer.class);
		for (TickActionEvent event : recorder.getRecordedAt(tickIndex).actions())
		{
			if (event.category() == TickActionCategory.PROTECTION_PRAYER)
			{
				out.add(Prayer.values()[event.primaryId()]);
			}
		}
		return out;
	}

