		assertTrue(prayersAt(1).isEmpty());
	}

	@Test
	public void movementDuringActiveSessionDoesNotExtendArmWindow()
	{
		// armTicks is the TOTAL capture length, not "ticks per movement".
		// First movement arms the window; later movements within the same
		// session don't refresh armRemaining. (Refreshing would let a
		// click-to-walk run extend the session indefinitely and silently
		// overwrite the click that started it once the cycle wrapped.)
		recorder.setMode(RecordMode.ARM);
		// Move on tick 0; armTicks=2 → arm window starts, capture slot 0.
		recorder.onTick(0, events(MELEE), true, 2);
		// Move again on tick 1 — already armed, no refresh. Window decrements
		// to 0 here and the recorder auto-exits.
		recorder.onTick(1, events(MAGIC), true, 2);
		// Further movement after auto-exit does not re-arm — that requires
		// a fresh setMode(ARM).
		recorder.onTick(2, events(MISSILE), true, 2);

		assertEquals(MELEE, prayersAt(0));
		assertEquals(MAGIC, prayersAt(1));
		assertTrue(prayersAt(2).isEmpty());
	}

	@Test
	public void armTicksAtLeastOneEvenWhenConfigIsZeroOrNegative()
	{
		recorder.setMode(RecordMode.ARM);
		// Defensive: bad config shouldn't silently disable the recorder.
		recorder.onTick(0, events(MELEE), true, 0);
		recorder.onTick(1, events(MAGIC), false, 0);

		assertEquals(MELEE, prayersAt(0));
		assertTrue(prayersAt(1).isEmpty());
	}

