	}

	// ─── ARM cycle wraparound ───────────────────────────────────────────

	@Test
	public void armDoesNotOverwriteYellowClickWhenCycleWrapsDuringContinuousMovement()
	{
		// Repro for the user-visible bug: in ARM mode, clicking-to-walk and
		// then continuing to move every tick refreshes armRemaining via the
		// movement branch. The session outlives one cycle's worth of ticks
		// and, on wrap, the original click's slot is overwritten with the
		// next tick's (empty) payload. Prayers don't show the bug because
		// they're continuous state — re-captured at the same slot the next
		// cycle. Momentary clicks/item-uses are not.
		recorder.setMode(RecordMode.ARM);

		List<TickActionEvent> yellow = Collections.singletonList(
			TickActionEvent.of(TickActionCategory.YELLOW_CLICK, TickActionEvent.NONE));

		// Cycle length 2 → slots {0, 1}. armTicks = 2 (max).
		recorder.onTick(0, yellow, true, 2);                  // slot 0: yellow click
		recorder.onTick(1, Collections.emptyList(), true, 2); // slot 1: still moving
		recorder.onTick(0, Collections.emptyList(), true, 2); // slot 0 again — must NOT overwrite

		RecordedTick slot0 = recorder.getRecordedAt(0);
		assertFalse(
			"yellow click at slot 0 was overwritten by an empty payload after the cycle wrapped",
			slot0.isEmpty());
		assertEquals(TickActionCategory.YELLOW_CLICK,
			slot0.actions().get(0).category());
	}

	@Test
	public void armDoesNotOverwriteItemUseWhenCycleWrapsDuringContinuousMovement()
	{
		// Same shape as the yellow-click case. Item-use rides the same
		// recorder pipeline, so the cycle-wraparound overwrite hits it
		// identically — pinning it down separately so the regression catches
		// any future divergence between click and item-use handling.
		recorder.setMode(RecordMode.ARM);

		List<TickActionEvent> itemUse = Collections.singletonList(
			TickActionEvent.of(TickActionCategory.ITEM_USE, 946, 1511));

		recorder.onTick(0, itemUse, true, 2);
		recorder.onTick(1, Collections.emptyList(), true, 2);
		recorder.onTick(0, Collections.emptyList(), true, 2);

		RecordedTick slot0 = recorder.getRecordedAt(0);
		assertFalse(
			"item-use at slot 0 was overwritten by an empty payload after the cycle wrapped",
			slot0.isEmpty());
		assertEquals(TickActionCategory.ITEM_USE, slot0.actions().get(0).category());
		assertEquals(946, slot0.actions().get(0).primaryId());
		assertEquals(1511, slot0.actions().get(0).secondaryId());
	}

